        }

        require_once('bibliotecas/validacoes/validaT006.php');
        if(!empty($return)){
            $retorno .= "PRODUTOS:\n";
            $retorno .= $return."\n\n";
        }

        //VALIDAÇÃO DO FORMULÁRIO
