	/**
	 * Vincula à NF de venda todas as NF-e de débito tipo 06 autorizadas dos
	 * pedidos de origem. Funciona tanto no faturamento direto quanto nos fluxos
	 * de separação/conferência/expedição e pode ser chamado mais de uma vez.
	 */
	public function sincronizarPagamentoAntecipadoVenda($T007_Id, $pedidos)
	{
		$T007_Id = (int) $T007_Id;
		if ($T007_Id <= 0) {
			return true;
		}
		$listaPedidos = is_array($pedidos) ? $pedidos : preg_split('/[^0-9]+/', (string) $pedidos, -1, PREG_SPLIT_NO_EMPTY);
		$idsPedidos = array();
		foreach ($listaPedidos as $T005_Id) {
			$T005_Id = (int) $T005_Id;
			if ($T005_Id > 0) {
				$idsPedidos[$T005_Id] = $T005_Id;
			}
		}
		if (empty($idsPedidos)) {
			$pedidosVendaSql = mysql_query("SELECT T007_T005_Id AS T005_Id FROM T007 WHERE T007_Id = '{$T007_Id}' AND IFNULL(T007_T005_Id,0) > 0
										 UNION SELECT T005_Id FROM T005 WHERE T005_T007_Id = '{$T007_Id}'");
			if (!$pedidosVendaSql) {
				return 'Não foi possível consultar os pedidos da NF de venda para vincular o pagamento antecipado: ' . mysql_error();
			}
			while ($pedidosVendaSql && $pedidoVenda = mysql_fetch_assoc($pedidosVendaSql)) {
				$pedidoVendaId = (int) $pedidoVenda['T005_Id'];
				if ($pedidoVendaId > 0) {
					$idsPedidos[$pedidoVendaId] = $pedidoVendaId;
				}
			}
		}
		if (empty($idsPedidos)) {
			return true;
		}

		// Nos fluxos agrupados, pesquisar notas somente dos pedidos sinalizados.
		$pedidosSql = implode(',', $idsPedidos);
		$pedidosAntecipadosSql = mysql_query("SELECT T005A_T005_Id AS T005_Id FROM T005A
											 WHERE T005A_T005_Id IN ({$pedidosSql})
											   AND T005A_Flag_Pagamento_Antecipado = 'S'");
		if (!$pedidosAntecipadosSql) {
			return 'Não foi possível consultar a sinalização de pagamento antecipado dos pedidos: ' . mysql_error();
		}
		$idsPedidos = array();
		while ($pedidoAntecipado = mysql_fetch_assoc($pedidosAntecipadosSql)) {
			$idsPedidos[] = (int) $pedidoAntecipado['T005_Id'];
		}
		if (empty($idsPedidos)) {
			return true;
		}

		$notaVendaSql = mysql_query("SELECT T007_C004_Id, T007_D024_Id, T007_Flag_Finalidade_NFe, T007_Numero_Protocolo_Nfe
									 FROM T007 WHERE T007_Id = '{$T007_Id}' LIMIT 1");
		$notaVenda = $notaVendaSql ? mysql_fetch_assoc($notaVendaSql) : false;
		if (!$notaVenda) {
			return 'NF de venda não encontrada para vincular o pagamento antecipado.';
		}
		if ((string) $notaVenda['T007_Flag_Finalidade_NFe'] !== '1') {
			return true;
		}
		// Documento autorizado é imutável. A sincronização ocorre durante a
		// geração da venda ou na recuperação de uma venda ainda em elaboração.
		if (!empty($notaVenda['T007_Numero_Protocolo_Nfe'])) {
			return true;
		}

		$pedidosSql = implode(',', $idsPedidos);
		$antecipacoesSql = mysql_query("SELECT DISTINCT NFDC.T007_Id,
												 NFDC.T007_Numero_Nota_Fiscal,
												 NFDC.T007_Chave_Acesso_Nfe,
												 NFDC.T007_Numero_Protocolo_Nfe,
												 NFDC.T007_C004_Id,
												 NFDC.T007_D024_Id
										  FROM T006 PEDITEM
									 INNER JOIN T008 NFDCITEM ON NFDCITEM.T008_T006_Id = PEDITEM.T006_Id
									 INNER JOIN T007 NFDC ON NFDC.T007_Id = NFDCITEM.T008_T007_Id
									 INNER JOIN T007A NFDCA ON NFDCA.T007A_T007_Id = NFDC.T007_Id
										 WHERE PEDITEM.T006_T005_Id IN ({$pedidosSql})
										   AND NFDC.T007_Flag_Finalidade_NFe = '6'
										   AND NFDCA.T007A_Tipo_NF_Debito = '06'
										   AND IFNULL(NFDC.T007_Flag_Cancelada,'N') != 'S'
										   AND IFNULL(NFDC.T007_Flag_Inutilizado,'N') != 'S'");
		if (!$antecipacoesSql) {
			return 'Não foi possível localizar as NF-e de pagamento antecipado: ' . mysql_error();
		}

		while ($antecipacao = mysql_fetch_assoc($antecipacoesSql)) {
			$identificacao = !empty($antecipacao['T007_Numero_Nota_Fiscal']) ? $antecipacao['T007_Numero_Nota_Fiscal'] : 'ID ' . $antecipacao['T007_Id'];
			if ((int) $antecipacao['T007_C004_Id'] !== (int) $notaVenda['T007_C004_Id'] || (int) $antecipacao['T007_D024_Id'] !== (int) $notaVenda['T007_D024_Id']) {
				return "A NF de débito tipo 06 {$identificacao} pertence a empresa ou cliente diferente da NF de venda.";
			}
			$chave = preg_replace('/\D/', '', (string) $antecipacao['T007_Chave_Acesso_Nfe']);
			if (strlen($chave) !== 44 || empty($antecipacao['T007_Numero_Protocolo_Nfe'])) {
				return "A NF de débito tipo 06 {$identificacao} ainda não está autorizada e não pode ser referenciada pela venda.";
			}
			$numero = (int) $antecipacao['T007_Numero_Nota_Fiscal'];

			// Repara registros gerados pela primeira versão, quando o ENUM recebeu
			// um tipo inválido e foi persistido vazio pelo MySQL não estrito.
			$reparouReferencia = mysql_query("UPDATE T132
							SET T132_Tipo = 'NFe', T132_Cupom_Modelo = 'PA'
						  WHERE T132_T007_Id = '{$T007_Id}'
							AND T132_Chave_Acesso = '{$chave}'
							AND IFNULL(T132_Tipo,'') = ''");
			if (!$reparouReferencia) {
				return 'Não foi possível atualizar a referência de pagamento antecipado na NF de venda: ' . mysql_error();
			}

			$inseriu = mysql_query("INSERT INTO T132 (T132_T007_Id, T132_Tipo, T132_Chave_Acesso, T132_Numero_Nota_Fiscal, T132_Cupom_Modelo)
								SELECT '{$T007_Id}', 'NFe', '{$chave}', '{$numero}', 'PA'
								 WHERE NOT EXISTS (SELECT 1 FROM T132
													WHERE T132_T007_Id = '{$T007_Id}'
													  AND T132_Chave_Acesso = '{$chave}'
													  AND T132_Tipo = 'NFe'
													  AND T132_Cupom_Modelo = 'PA')");
			if (!$inseriu || mysql_error()) {
				return 'Não foi possível gravar a referência de pagamento antecipado na NF de venda: ' . mysql_error();
			}
		}

		return true;
	}

	/**
	 * Impede a geração da NF de venda enquanto uma antecipação vinculada ao
	 * pedido ainda não puder ser referenciada por chave autorizada.
	 */
	public function validarPagamentoAntecipadoPedido($T005_Id)
	{
		$T005_Id = (int) $T005_Id;
		if ($T005_Id <= 0) {
			return 'Pedido não encontrado para validar o pagamento antecipado.';
		}
		// Busca pelo pedido e seu complemento indexado, sem cruzar as notas.
		// Pedido sem registro estendido ainda não possui antecipação gerada.
		$pedidoSql = mysql_query("SELECT IFNULL(T005A_Flag_Pagamento_Antecipado, 'N') AS T005A_Flag_Pagamento_Antecipado
								 FROM T005 LEFT JOIN T005A ON T005A_T005_Id = T005_Id
								 WHERE T005_Id = '{$T005_Id}' LIMIT 1");
		if (!$pedidoSql) {
			return 'Não foi possível consultar a sinalização de pagamento antecipado do pedido: ' . mysql_error();
		}
		$pedido = mysql_fetch_assoc($pedidoSql);
		if (!$pedido) {
			return 'Pedido não encontrado para validar o pagamento antecipado.';
		}
		if ($pedido['T005A_Flag_Pagamento_Antecipado'] === 'N') {
			return true;
		}
		$sql = mysql_query("SELECT DISTINCT NFDC.T007_Id,
										   NFDC.T007_Numero_Nota_Fiscal,
										   NFDC.T007_Chave_Acesso_Nfe,
										   NFDC.T007_Numero_Protocolo_Nfe,
										   NFDC.T007_D024_Id,
										   NFDC.T007_C004_Id,
										   PEDIDO.T005_D024_Id,
										   PEDIDO.T005_C004_Id
									  FROM T006 PEDITEM
								 INNER JOIN T005 PEDIDO ON PEDIDO.T005_Id = PEDITEM.T006_T005_Id
								 INNER JOIN T008 NFDCITEM ON NFDCITEM.T008_T006_Id = PEDITEM.T006_Id
								 INNER JOIN T007 NFDC ON NFDC.T007_Id = NFDCITEM.T008_T007_Id
								 INNER JOIN T007A NFDCA ON NFDCA.T007A_T007_Id = NFDC.T007_Id
									 WHERE PEDITEM.T006_T005_Id = '{$T005_Id}'
									   AND NFDC.T007_Flag_Finalidade_NFe = '6'
									   AND NFDCA.T007A_Tipo_NF_Debito = '06'
									   AND IFNULL(NFDC.T007_Flag_Cancelada,'N') != 'S'
									   AND IFNULL(NFDC.T007_Flag_Inutilizado,'N') != 'S'");
		if (!$sql) {
			return 'Não foi possível validar as NF-e de pagamento antecipado: ' . mysql_error();
		}
		while ($nota = mysql_fetch_assoc($sql)) {
			if ((int) $nota['T007_D024_Id'] !== (int) $nota['T005_D024_Id'] || (int) $nota['T007_C004_Id'] !== (int) $nota['T005_C004_Id']) {
				return 'A NF de débito por pagamento antecipado foi emitida para cliente ou empresa diferente do pedido. Corrija/cancele a antecipação antes de gerar a NF de venda.';
			}
			if (strlen($nota['T007_Chave_Acesso_Nfe']) !== 44 || empty($nota['T007_Numero_Protocolo_Nfe'])) {
				$identificacao = !empty($nota['T007_Numero_Nota_Fiscal']) ? $nota['T007_Numero_Nota_Fiscal'] : 'Em elaboração #' . $nota['T007_Id'];
				return "A NF de débito por pagamento antecipado {$identificacao} ainda não foi autorizada. Autorize-a antes de gerar a NF de venda, pois sua chave deve constar no cabeçalho em gPagAntecipado/refNFe.";
			}
		}
		return true;
	}

