                          left join D053 on D053_D018_Id=D024_D018_Id AND D053_C004_Id=T005_C004_Id
                          left join D036 on D036_Id=T005_D036_Id
                          left join C004 on C004_Id=T005_C004_Id
                          left join D020 as cidadeEmpresa on cidadeEmpresa.D020_Id=C004_D020_Id 
                          left join D018 as ufEmpresa on ufEmpresa.D018_Id=C004_D018_Id
