                          left join D018 as ufCliente on ufCliente.D018_Id=D024_D018_Id 
                          left join D030 on D030_Id=D024_D030_Id 
                          left join D022 on D022_Id=T005_D022_Id
                          left join D020 as cidadeTransportadora on cidadeTransportadora.D020_Id=D022_D020_Id 
                          left join D018 as ufTransportadora on ufTransportadora.D018_Id=D022_D018_Id
                          left join D148 on D148_Id=T005_D148_Id_entrega
                          left join D020 as cidadeEntrega on cidadeEntrega.D020_Id=D148_D020_Id 
                          left join D018 as ufEntrega on ufEntrega.D018_Id=D148_D018_Id
                             where T005_Id='{$T005_Id}'");        
        
        $mT005 = mysql_fetch_array($T005);

        //////////////////////////////////////////////////////////////////
        //                                                              //
        //       ATUALIZA CLASSIFICACOES DA NOTA EMITIDA                //
        //                                                              //
        //////////////////////////////////////////////////////////////////
        $Empresa_Grupo = 'N';
        if ((substr($mT005['D024_Nome_Empresa'], 0, 6) == "D.M.R.") OR (substr($mT005['D024_Nome_Empresa'], 0, 9) == "ENGEPECAS")) {
            $Empresa_Grupo = 'S';
        }
        
        // VENDA NORMAL     
        if (($mT005['D006_Flag_Entrada_Saida'] == 'S') and ($mT005['D006_Flag_Venda_Maquina'] != 'S') and ($mT005['D006_Flag_Gera_Contas'] == 'R') and ($mT005['D006_Flag_Devolucao'] != 'S') and ($mT005['D006_Flag_Venda_Compra_Outros'] == 'V') and ($mT005['D024_Flag_Mono'] != '1') and ($Empresa_Grupo == 'N')) {
            $Classificacao = 1;
        }
        
        
        // TRANSFERENCIA      
        if (($mT005['D006_Flag_Entrada_Saida'] == 'S') and ($mT005['D006_Flag_Gera_Contas'] == 'R') and ($mT005['D006_Flag_Devolucao'] != 'S') and ($mT005['D006_Flag_Venda_Compra_Outros'] == 'T')) {
            $Classificacao = 4;
        }
        
        // VENDA PARA EMPRESAS DO GRUPO
        if (($mT005['D006_Flag_Entrada_Saida'] == 'S') and ($mT005['D006_Flag_Venda_Maquina'] != 'S') and ($mT005['D006_Flag_Gera_Contas'] == 'R') and ($mT005['D006_Flag_Devolucao'] != 'S') and ($mT005['D006_Flag_Venda_Compra_Outros'] == 'V') and (($mT005['D024_Flag_Mono'] == '1') or ($Empresa_Grupo == 'S'))) {
            $Classificacao = 5;
        }
        
        
        // IMPORTACAO
        if (($mT005['D006_Flag_Entrada_Saida'] == 'E') and ($mT005['D006_Flag_Devolucao'] != 'S') and ($mT005['D006_Flag_Venda_Compra_Outros'] == 'O') and ($mT005['D006_Flag_Estado'] == 'I') and ($mT005['D024_Flag_Mono'] != '1') and ($Empresa_Grupo == 'N')) {
            $Classificacao = 3;
        }
        
        
        // DEVOLUCAO VENDA
        if (($mT005['D006_Flag_Entrada_Saida'] == 'E') and ($mT005['D006_Flag_Venda_Maquina'] != 'S') and ($mT005['D006_Flag_Devolucao'] == 'S') and ($mT005['D006_Flag_Venda_Compra_Outros'] == 'C') and ($mT005['D024_Flag_Mono'] != '1') and ($Empresa_Grupo == 'N')) {
            $Classificacao = 2;
        }
               
        //Seta a flag destino operação
        if($mT005['empresa_D018_Id'] == $mT005['cliente_D018_Id']){
            $T007_Flag_Destino_Operacao = '1';
        } else if($mT005['empresa_D018_Id'] != $mT005['cliente_D018_Id'] && $mT005['cliente_D018_UF'] != 'EX') {
            $T007_Flag_Destino_Operacao = '2';
        } else {
            $T007_Flag_Destino_Operacao = '3';
        }

        //Seta o CNPJ/CPF do cliente
        if ($mT005['D024_Flag_Pessoa_Fisica_Juridica'] == 'J') {
            $D007_Cliente_CNPJ_CPF = "{$mT005['D024_Cnpj']}";
        } elseif ($mT005['D024_Flag_Pessoa_Fisica_Juridica'] == 'I') {
            $D007_Cliente_CNPJ_CPF = "{$mT005['C004_Cnpj']}";
        } else {
            $D007_Cliente_CNPJ_CPF = "{$mT005['D024_Cpf']}";
        }
            

        mysql_query("LOCK T238"); 
        mysql_query("LOCK T118");
        mysql_query("LOCK T178");
        mysql_query("LOCK T007");
        mysql_query("START TRANSACTION");
        
        //retorna a proxima numeração e série da nota fiscal
        $proximoNumeroSerie = $this->retornaProximaNF($mT005['T005_Flag_ACP'], $mT005['T005_C004_Id']);

        list($proximoNumero,$retorno1) = $proximoNumeroSerie;
        if($proximoNumero === false){
            return $retorno1;
        }

        if ($mT005['T005_Flag_ACP'] == 6) {

            $dataFiltroNota     = strtotime("-15 day", strtotime(date("Y-m-d")));
            $dataFiltroNota = date("Y-m-d", $dataFiltroNota);

            $notaf = mysql_query("SELECT T007_Numero_Nota_Fiscal, 
                                         T007_Empresa_Usuaria_Cnpj,
                                         T007_Data_Emissao
                                    FROM T007
                                   WHERE T007_Data_Emissao >= '$dataFiltroNota'
                                     AND T007_Flag_ACP='6'
                                     AND T007_C004_Id='{$mT005['T005_C004_Id']}'
                                     AND T007_Serie='{$retorno1}'
                                     AND round(T007_Numero_Nota_Fiscal) > 0
                                ORDER BY round(T007_Numero_Nota_Fiscal) DESC LIMIT 1");

            if (mysql_num_rows($notaf) <=0) {
                $notaf = mysql_query("SELECT T007_Numero_Nota_Fiscal, 
                                             T007_Empresa_Usuaria_Cnpj,
                                             T007_Data_Emissao
                                        FROM T007
                                       WHERE T007_Flag_ACP='6'
                                         AND T007_C004_Id='{$mT005['T005_C004_Id']}'
                                         AND T007_Serie='{$retorno1}'
                                    ORDER BY round(T007_Numero_Nota_Fiscal) DESC LIMIT 1");
            }
            $mT007 = mysql_fetch_array($notaf);

            $sqlCheckDB = mysql_query("SELECT DATABASE()");
            $rowCheckDB = mysql_fetch_array($sqlCheckDB);
            $dbCheck = strtolower($rowCheckDB[0]);
            $dbCheck = str_replace('_novo', '', $dbCheck); //Removendo _novo da base das empresa que foram atualizadas
            $C004dbCheck = strtolower($mT005['C004_Banco_Dados']);
            $C004dbCheck = str_replace('_novo', '', $C004dbCheck);
            $C004_Cnpj = str_replace(array(".","-","/"), "", $mT005['C004_Cnpj']);
            $T007_Empresa_Usuaria_Cnpj = str_replace(array(".","-","/"), "", $mT007['T007_Empresa_Usuaria_Cnpj']);

            //VP35 - Se o cnpj da empresa for diferente do cnpj da ultima nota fiscal
            if(($C004_Cnpj != $T007_Empresa_Usuaria_Cnpj && !empty($mT007['T007_Numero_Nota_Fiscal']))){
                return "O CNPJ da última nota fiscal emitida (".$T007_Empresa_Usuaria_Cnpj.") está diferente do CNPJ (".$C004_Cnpj.") do cadastro da empresa. Verifique!";
            }

            //VP36 - se o banco de dados aberto for diferente do que esta configurado na empresa
            if($C004dbCheck != $dbCheck){
                return "O banco de dados atual (".$dbCheck.") é diferente do banco de dados configurado nesta empresa (".$C004dbCheck."). Informar o suporte técnico.";
            }
        }
        
        //Calcula o total de duplicatas
        if ($mT005['T005_Valor_Entrada'] > 0) {
            $Total_Duplicatas++;
        }
        
        if (($mT005['T005_Valor_Total'] > 0) and ($mT005['T005_Valor_Entrada'] != $mT005['T005_Valor_Total'])) {
            $Total_Duplicatas += $mT005['T005_Numero_Parcelas'];
        }
                
        //-- Agrega as observações fiscais
        $Observacao_Fiscal = "";
        if (!empty($mT005['T005_Observacao']) && $g['C031']['exibirObservacaoClienteNF']=='S') {
            $Observacao_Fiscal .= $mT005['T005_Observacao'] . ' ';
        }

        if($g['C031']['exibirObservacaoPedidonaNF']=='S'){
            $Observacao_Fiscal .= 'PEDIDO: ' . $mT005['T005_Id']; 
        }
        if($g['C031']['exibirObservacaoVendedornaNF']=='S'){
            $Observacao_Fiscal .= ' VENDEDOR: ' . substr($mT005['C007_Primeiro_Nome'], 0, 12);
        }

        if (!empty($mT005['T005_Ordem_Compra']) && $g['C031']['exibirObservacaoOCnaNF']=='S') {
            $mT005['T005_Ordem_Compra'] = ' OC: ' . mysql_real_escape_string($mT005['T005_Ordem_Compra']);
            $Observacao_Fiscal .= $mT005['T005_Ordem_Compra'];
        }
        $Observacao_Fiscal .= ';'; //Quebra linha
        
        if (!empty($mT005['T005_Cliente_Area']) && $mT005['T005_Cliente_Area'] != '' && $g['C031']['exibirObservacaoAreaClientenaNF'] == 'S') {
            $Observacao_Fiscal .= 'AREA: ' . $mT005['T005_Cliente_Area'] . ' ';
        }
        if ($mT005['T005_D013_Id'] > 0 && $g['C031']['exibirObservacaoContatonaNF'] == 'S') {
            $Observacao_Fiscal .= 'CONTATO: ' . substr($mT005['D013_Nome_Contato'], 0, 12);
        }
        if ($mT005['T005_D036_Id'] > 0 && $g['C031']['exibirTipoFreteNaNF'] == 'S') {
            $Observacao_Fiscal .= 'TIPO FRETE: ' . substr($mT005['D036_Tipo_Transporte'], 0, 12).' ';
        }
        $Observacao_Fiscal .= ';'; //Quebra linha
        
        if (!empty($mT005['C004_Observacao_Fiscal'])) {
            $Observacao_Fiscal .= $mT005['C004_Observacao_Fiscal'];
        }
        if (!empty($mT005['T005_Observacao_Nota_Fiscal'])) {
            if (!empty($Observacao_Fiscal)) {
                $Observacao_Fiscal .= "\n";
            }
            $Observacao_Fiscal .= $mT005['T005_Observacao_Nota_Fiscal'] . ';';
        }

        if (!empty($mT005['T005_D148_Id_Entrega'])) {
            if (!empty($Observacao_Fiscal)) {
                //$Observacao_Fiscal .= ';';
            }

            $endereco = !empty($mT005['D148_Numero']) ? $mT005['D148_Rua'].", ".$mT005['D148_Numero'] : $mT005['D148_Rua'];
            $endereco .= !empty($mT005['D148_Complemento']) ? " - ".$mT005['D148_Complemento'] : '';
            //$Observacao_Fiscal = trim($Observacao_Fiscal, ';');
            $Observacao_Fiscal .= "ENDEREÇO DE ENTREGA: {$endereco} - {$mT005['entrega_D020_Nome_Cidade']} - {$mT005['entrega_D018_UF']} - Bairro: {$mT005['D148_Bairro']} - CEP: {$mT005['D148_Cep']} ";
        }
        
        //VP40 - 5000 caracteres é o limite disponibilizado para sefaz conforme a nota técnica NT2013.005_v1.21
        if (strlen($Observacao_Fiscal) > 5000) {
            mysql_query("ROLLBACK");
            return "Observação fiscal ultrapassou 5000 caracteres, volte o pedido e diminua o tamanho da observação fiscal.Este campo esta com " . strlen($Observacao_Fiscal) . " caracteres') <br />" . str_replace(";", "<br />", $Observacao_Fiscal);
        }
        
        if (($mT005['T005_Valor_Total_ICMS'] <= 0) and (empty($Observacao_Fiscal)) and (($mT005['T005_Flag_ACP'] == 1) or ($mT005['T007_Flag_ACP'] == 4))) {
            //VP41
            mysql_query("ROLLBACK");
            return 'NOTA NAO PODE SER GERADA. VALOR DO ICMS ESTA ZERADO E NAO EXISTE OBSERVACAO FISCAL';
        }

        //FIM DA VALIDAÇÃO---------------------------------------------------------------------------------------------------------------------

        // INICIO PROCESSO SEPARAÇÃO ----------------------------------------------------------------------------
        // Adicionado verificação para que se a global StatusInicialPedido for definido como 3 o sistema preenche a separação

        if($g['C031']['statusInicialPedido']=='3' || $g['C031']['desabilitarSeparacao']=='S'){
            
            $sql = <<<EOT
            select T006_Id,
                   T006_Quantidade,
                   T006_Quantidade_Separacao,
                   T006_T005_Id,
                   T006_T066_Id,
                   GROUP_CONCAT(DISTINCT T066_Id SEPARATOR '|') AS T066_Id_Mais       
              from T006
         left join T066 ON T066_D009_Id=T006_D009_Id
         left join D009 ON D009_Id=T006_D009_Id
         left join D049 ON D049_Id=D009_D049_Id
         left join D001 ON D001_Id=D049_D001_Id
         left join T005 ON T005_Id=T006_T005_Id
             where T006_T005_Id='{$T005_Id}'
               and ifnull(T006_Quantidade_Separacao, 0) < T006_Quantidade
               and if(ifnull(T006_C004_Id_Estoque,0) > 0, T006_C004_Id_Estoque, T005_C004_Id) = T005_C004_Id
          group by T006_Id                                   
EOT;
            $resT006 = mysql_query($sql);
            if (mysql_num_rows($resT006) > 0) {
                //Preencher a separação
                $produtosSemLocal = 0;
                $locacaoSemEstoque = 0;
                while ($rowT006 = mysql_fetch_assoc($resT006)) {
                    $T066_Id = $rowT006['T006_T066_Id'];
                    if ($T066_Id) {
                        $D004_Id = getD004($T066_Id);
                        //echo "{$rowT006['T006_Id']} - {$rowT006['D001_Codigo_Produto']} - $T066_Id - $D004_Id <br/>";
                        // Separa
                        $rowT006['T006_Quantidade_Separacao'] = empty($rowT006['T006_Quantidade_Separacao']) ? 0 : $rowT006['T006_Quantidade_Separacao'];
                        $rowT006['T006_Quantidade'] = empty($rowT006['T006_Quantidade']) ? 0 : $rowT006['T006_Quantidade'];
                        if($g['C031']['permitirFaturarSemEstoque'] == 'S'){

                            $sqlQtdeSeparacao = mysql_query("select sum(T238_Quantidade_Separacao) as Quantidade_Separacao 
                                                               from T238 
                                                              where T238_T006_Id = '{$rowT006['T006_Id']}'");

                            $rowQtdeSeparacao = mysql_fetch_array($sqlQtdeSeparacao);
                            $rowT006['T006_Quantidade_Separacao'] = $rowQtdeSeparacao['Quantidade_Separacao'];
                        } else {

                            $sqlT066 = mysql_query("select T066_Quantidade_Estoque 
                                                      from T066 
                                                     where T066_Id = '{$T066_Id}'");
                            $rowT066 = mysql_fetch_array($sqlT066);
                        }
                        $qtd = $rowT006['T006_Quantidade'] - $rowT006['T006_Quantidade_Separacao'];

                        //Verifica se a primeira locação possui estoque suficiente
                        if($rowT066['T066_Quantidade_Estoque'] < $qtd && $g['C031']['permitirFaturarSemEstoque'] == 'N'){
                            $locacaoSemEstoque++;
                        } else {
                            $sql = "INSERT INTO T238 (
                                                T238_T005_Id, 
                                                T238_T006_Id, 
                                                T238_T066_Id, 
                                                T238_D004_Id, 
                                                T238_Quantidade_Separacao
                                                ) VALUES (
                                                '{$rowT006['T006_T005_Id']}', 
