                        mysql_query("ROLLBACK");
                        return $locacaoSemEstoque . " produto não possui estoque suficiente na primeira locação.";
                    } else {
                        mysql_query("ROLLBACK");
                        return $locacaoSemEstoque . " produtos não pussuem estoque suficiente na primeira locação.";
                    }
                }
            }
        }

        // Trava: Não é possível gerar uma nota de um pedido não separado (não deveria acontecer... mais já apareceu 2 casos na ceigon, por isso a trava)
                            
        $res = mysql_query("SELECT T006_Id,
                                   T238_Id,
                                   T006_Codigo_Produto,
