    /**
     * gerarNFincluirItens
     *
     * @param $T007_Id
     * @param $T005_Id
     * @param array $mT006
     */
    public function gerarNFincluirItens($T007_Id, $T005_Id, $mT006)
    {
        global $g, $confUsuario;

        $D048_Id           = 1;
        $cSql_T005 = mysql_query("select T005_Id,
                                         D053_Percentual_FCP,
                                         T005_Flag_ACP,
                                         T005_D024_Id,
                                         T005_D006_Id,
                                         T005_C004_Id,
                                         T006_D006_Id,
                                         D006_Flag_Estoque,
                                         D006_Flag_MMF,
                                         D006_Flag_Atualiza_Custo,
                                         D006_Flag_Unidade_Tributavel,
                                         C004_Casas_Decimais_Preco,
                                         C004_Flag_Controla_Estoque
                                    from T005 
                               left join T006 on T006_T005_Id=T005_Id
                               left join D024 on T005_D024_Id=D024_Id
                               left join D018 on D024_D018_Id=D018_Id
                               left join D053 on D053_D018_Id=D018_Id
                               left join D006 on T005_D006_Id=D006_Id
                               left join C004 on T005_C004_Id=C004_Id
                                   where T005_Id='$T005_Id'");
        $mT005 = mysql_fetch_array($cSql_T005);       

        $cSql_T007 = mysql_query("select T007_Flag_Classificacao,
                                         T007_Numero_Nota_Fiscal
                                    from T007 
                                   where T007_Id='$T007_Id'");
        $mT007     = mysql_fetch_array($cSql_T007);
        $mT007['Proximo_Numero'] = $mT007['T007_Numero_Nota_Fiscal'];
        $Classificacao = $mT007['T007_Flag_Classificacao'];       
  
        //////////////////////////////////////////////////////////////////////////////////////
        // INCLUSAO DOS ITENS DA NOTA
        //////////////////////////////////////////////////////////////////////////////////////

        if ($mT005['D006_Flag_Estoque'] == 'D') {
            $Flag_Operacao_Historico = "S";
        } elseif ($mT005['D006_Flag_Estoque'] == 'C') {
            $Flag_Operacao_Historico = "E";
        } elseif ($mT005['D006_Flag_Estoque'] == 'N') {
            $Flag_Operacao_Historico = "N";
        }
        
        if (!empty($mT006['D049_Codigo_Barras'])) {
            $Codigo_Barras = $mT006['D049_Codigo_Barras'];
        } else {
            $Codigo_Barras = $mT006['D001_Codigo_Barras'];
        }
        // Verifica se o código de barras tributavel está preenchido, caso não esteja será utilizado o código de barras.
        if(empty($mT006['D001_Codigo_Barras_Tributavel'])){
            $mT006['D001_Codigo_Barras_Tributavel']=$Codigo_Barras;
        }
        
        $mT006['T006_Descricao_Produto'] = addslashes($mT006['T006_Descricao_Produto']);
        $mT006['T006_Codigo_Substituto'] = addslashes($mT006['T006_Codigo_Substituto']);
        $mT006['T006_Codigo_Produto']    = addslashes($mT006['T006_Codigo_Produto']);
        $Classificacao_Fiscal            = $mT006['T006_D005_Id'];
        $mClassificacao_Fiscal[$Classificacao_Fiscal] = str_pad($mT006['T006_D005_Id'], 2, "0", STR_PAD_LEFT);
        
        if (!empty($mT006['T006_Codigo_Substituto'])) {
            $Codigo_Produto_Nota = $mT006['T006_Codigo_Substituto'];
        } else {
            $Codigo_Produto_Nota = $mT006['T006_Codigo_Produto'];
        }
        $Codigo_Produto_Nota = '';
        $mT006['T006_D006_Id_Info'] = mysql_real_escape_string($mT006['T006_D006_Id_Info']);

        // BUSCANDO O VALOR DO CEST NA NCM PARA EXIBIR NA 
