     * gerarNotaFiscal
     *
     * @param Form $form
     */
    public function gerarNFContas($T007_Id, $form)
    {

        global $g;
        global $confUsuario;
        $T005_Id              = $form['T005_Id'];
        $D024_Nome_Empresa    = $form['D024_Nome_Empresa'];
        $T005_D024_Id_Nfe     = $form['T005_D024_Id_Nfe'];
        $T005_D024_Id_Contas  = $form['T005_D024_Id_Contas'];

        $mTipoDocumento[1] = "NOTA FISCAL";
        $mTipoDocumento[3] = "ACP";
        $mTipoDocumento[4] = "CUPOM FISCAL";
        $mTipoDocumento[5] = "NOTA FISCAL D1";
        $mTipoDocumento[6] = "NF-e";
        $mTipoDocumento[7] = "NFS-e";

        if ($T005_D024_Id_Nfe <= 0) {
            $T005_LeftJoin = 'T005_D024_Id';
        } else {
            $T005_LeftJoin = 'T005_D024_Id_Nfe';
        }
        if ($T005_D024_Id_Contas <= 0) {
            $T005_D024_Id_Contas = $D024_Nome_Empresa;
        }

        $cSql_T005 = mysql_query("select D006_D014_Id,
                                         D006_D073_Id,
                                         T005_D006_Id,
                                         D014_D032_Id,
                                         D024_Data_Primeira_Compra,
                                         D036_Flag_Correios,
                                         T005_C004_Id,
                                         T005_D024_Id_Nfe,
                                         T005_D021_Id,
