        mysql_query("START TRANSACTION");

        
        $total_Parcelas = mysql_num_rows($cSql_T090);
        
        if (mysql_num_rows($cSql_T090) > 0) {
            
            if ($mT005['D006_Flag_Gera_Contas'] == 'R') {
                while ($mT090 = mysql_fetch_array($cSql_T090)) {
                    $Numero_Parcela   = $mT090['T090_Numero_Parcela'];
                    if ($mT005['T005_Flag_ACP'] == '4' && empty($mT007['Proximo_Numero'])) {
                        $mT007['Proximo_Numero'] = "C00001";
                    }
                    $Numero_Duplicata = $mT007['Proximo_Numero'] . $mLetras[$Numero_Parcela];
                    
                    $cSql_Vencimento = mysql_query("SELECT DATE_ADD(current_date(),INTERVAL {$mT090['T090_Prazos_Dias']} DAY) as Vencimento");
                    $mVencimento     = mysql_fetch_array($cSql_Vencimento);
                    
                    mysql_query("UPDATE T090 SET T090_Data_Vencimento='$mVencimento[0]' WHERE T090_Id='{$mT090['T090_Id']}'");
                    
                    $Valor_Base_Comissao_Titulo   = round(($mT090['T090_Valor_Parcela'] * $Valor_Total_Base_Comissao) / $mT007['T007_Valor_Total'], 2);
                    $Valor_Comissao               = round($Valor_Base_Comissao_Titulo * ($mT005['T005_Percentual_Comissao'] / 100), 2);
                    $Valor_Comissao_Representante = round($Valor_Base_Comissao_Titulo * ($mT005['T005_Percentual_Comissao_Representante'] / 100), 2);
                    $Valor_Comissao_Usuario       = round($Valor_Base_Comissao_Titulo * ($mT005['T005_Percentual_Comissao_Usuario'] / 100), 2);
                    $Valor_Comissao_Externo       = round($Valor_Base_Comissao_Titulo * ($mT005['T005_Percentual_Comissao_Externo'] / 100), 2);

                    if ($mT090['D027_Flag_Baixa_Automatica'] == 'S' and $mT090['D027_D007_Id'] > 0) {
                        $data_Emissao_Lancamento = date("Y-m-d");
                        //Caso exista prazo para a baixa automatica, o lançamento irá ser gravado com emissão igual a data atual mais o prazo
                        if($mT090['D027_Baixa_Automatica_Dias'] > 0){
                            $cSql_Vencimento = mysql_query("SELECT DATE_ADD(current_date(),INTERVAL {$mT090['D027_Baixa_Automatica_Dias']} DAY) as Vencimento");
                            $mVencimento     = mysql_fetch_array($cSql_Vencimento);
                            $data_Emissao_Lancamento = $mVencimento[0];
                        }
                    }
                    
                    $cClausula = " INSERT INTO T002 ( ";
                    $cClausula .= " T002_D024_Id, ";
                    $cClausula .= " T002_D021_Id, ";
                    $cClausula .= " T002_D027_Id, ";
