                    $cClausula .= " T002_Numero_Documento, ";
                    $cClausula .= " T002_Data_Emissao, ";
                    $cClausula .= " T002_Data_Vencimento, ";
                    $cClausula .= " T002_Data_Vencimento_Original, ";
                    $cClausula .= " T002_Data_Recebimento, ";
