    /*
    * EtapaRoolback = 1 ( Erro na validação do formulário)
    * EtapaRoolback = 2 ( Erro na totalização dos pedido)
    * EtapaRoolback = 3 ( Erro na montagem do cabeçalho da nota)
    * EtapaRoolback = 4 ( Erro na inclusão dos itens na nota)
    * EtapaRoolback = 5 ( Erro ao gerar contas)
    * EtapaRoolback = 6 ( Erro na totalização da nota)
    */ 
    public function roolbackNF($T005_Id, $T007_Id, $cache, $r_EtapaRoolback)
    {
        log("etapa Roolback: ".$r_EtapaRoolback);
        global $g;
        $concluido = false;
        log("%%variáveis do cache%%");
        log("T007_Id = ".$T007_Id);
        log("T005_Id = ".$T005_Id);
        log("D007_Nosso_Numero= ". $cache['D007_Nosso_Numero']);
        log("D024_Data_Primeira_Compra= ". $cache['D024_Data_Primeira_Compra']);
        log("D024_Data_Ultima_Compra= ". $cache['D024_Data_Ultima_Compra']);
        log("C004_Ultimo_Numero_Nota_Fiscal= ". $cache['C004_Ultimo_Numero_Nota_Fiscal']);
        log("C004_Ultimo_Numero_Nota_Fiscal_Eletronica= ". $cache['C004_Ultimo_Numero_Nota_Fiscal_Eletronica']);
        log("C004_Ultimo_Numero_Cupom_Fiscal= ". $cache['C004_Ultimo_Numero_Cupom_Fiscal']);
        log("C004_Ultimo_Numero_ACP= ". $cache['C004_Ultimo_Numero_ACP']);
        //Se ocorrer um erro na validação do formulário(1) ou na totalização do pedido(2)
        if($r_EtapaRoolback >= 1){ 
            log("OCORREU UM ERRO NA VALIDAÇÃO DO FORMULÁRIO OU NA TOTALIZAÇÃO DO PEDIDO");
            //volta o pedido para emitir nota
            mysql_query("UPDATE T005 
                            SET T005_Flag_Status = 3,
                                T005_Nome_Status = 'Emitir NF',
                                T005_Flag_Marcado = 'N' 
                          WHERE T005_Id= '{$T005_Id}'");
            log("ROOLBACK 01");
            $cErro = mysql_error();
            if (!empty($cErro)) {
                $retorno = "***ERRO!!***</br><b>Contate o suporte técnico e não tente gerar mais notas fiscais até que o problema seja resolvido!</b></br>ERRO Roolback01: " . $cErro;
                return $retorno;
            }

            //Se ocorrer um erro na montagem do cabeçalho(3)
            if($r_EtapaRoolback >= 3){ 
                log("OCORREU ERRO NA MONTAGEM DO CABEÇALHO");
                //pega o último histórico do pedido e deleta se tiver mudado para "enviou para coleta"
                $roolbackT178 = mysql_query("SELECT T178_Id 
                                               FROM T178
                                              WHERE T178_T005_Id = '{$T005_Id}'
                                                AND T178_Descricao = 'Enviou para coleta'
                                           ORDER BY T178_Data DESC");
                if(mysql_num_rows($roolbackT178) > 0){
                    $mRoolbackT178 = mysql_fetch_array($roolbackT178);
                    mysql_query("DELETE FROM T178 WHERE T178_Id='{$mRoolbackT178['T178_Id']}'");
                    log("ROOLBACK 02");
                    $cErro = mysql_error();
                    if (!empty($cErro)) {
                        $retorno = "***ERRO!!***</br><b>Por favor, contate o suporte técnico e não tente gerar mais notas fiscais até que o problema seja resolvido!</b></br>ERRO Roolback02: ";
                        return $retorno;
                    }
                }
                
                //limpar a T238(separação) e a T006_Quantidade_Separação
                $separacao = mysql_query("SELECT T238_Id FROM T238 WHERE T238_T005_Id='{$T005_Id}'");
                if(mysql_num_rows($separacao) > 0){
                    log("ROOLBACK 03");
                    mysql_query("DELETE FROM T238 WHERE T238_T005_Id='{$T005_Id}'");
                    $cErro = mysql_error();
                    if (!empty($cErro)) {
                        $retorno = "***ERRO!!***</br><b>Por favor, contate o suporte técnico e não tente gerar mais notas fiscais até que o problema seja resolvido!</b></br>ERRO Roolback03: " . $cErro;
                        return $retorno;
                    }
                }

                // Se ocorrer um erro na inclusão dos itens(4) 
                if($r_EtapaRoolback >= 4){ 
                    log("OCORREU ERRO NA INCLUSÃO DOS ITENS");
                    if(empty($T005_Id)){
                        //limpa o T186(T001 da locação)
                        $roolbackT186 = mysql_query("SELECT T186_Id, T001_Id 
                                                       FROM T186
                                                  LEFT JOIN T001 ON T186_T001_Id = T001_Id
                                                  LEFT JOIN T007 ON T001_T007_Id=T007_Id
                                                      WHERE T001_T007_Id='{$T007_Id}';");
                        if(mysql_num_rows($roolbackT186) > 0){
                            while($mRoolbackT186 = mysql_fetch_array($roolbackT186)){
                                mysql_query("DELETE FROM T186 WHERE T186_Id='{$mRoolbackT186['T186_Id']}'");
                                log("ROOLBACK 04");
                                $cErro = mysql_error();
                                if (!empty($cErro)) {
                                    $retorno = "***ERRO!!***</br><b>Por favor, contate o suporte técnico e não tente gerar mais notas fiscais até que o problema seja resolvido!</b></br>ERRO Roolback04: " . $cErro."<b></br>T007_Id: ".$T007_Id;
                                    return $retorno;
                                }
                            }
