                                         T005A_D148_Id_Redespacho,
                                         (SELECT D027_Cnpj_Intermediador_Transacao FROM T005 LEFT JOIN T090 ON T005_Id=T090_T005_Id LEFT JOIN D027 ON D027_Id=T090_D027_Id WHERE T005_Id='{$T005_Id}' AND IFNULL(D027_Cnpj_Intermediador_Transacao,'') != '' LIMIT 1) AS D027_Cnpj_Intermediador_Transacao
                                   FROM T005 
