                              LEFT JOIN D018 AS ufCliente ON ufCliente.D018_Id=D024_D018_Id 
                              LEFT JOIN D030 AS paisCliente ON paisCliente.D030_Id=D024_D030_Id
                              LEFT JOIN D022 ON D022_Id=T005_D022_Id
                              LEFT JOIN D036 ON D036_Id=IF(T005_D036_Id > 0,T005_D036_Id, D022_D036_Id)
