        }
        if($g['C031']['exibirObservacaoVendedornaNF']=='S'){
            $Observacao_Fiscal .= ' VENDEDOR: ' . substr($mT005['C007_Primeiro_Nome'], 0, 12);
        }

        if (!empty($mT005['T005_Ordem_Compra']) && $g['C031']['exibirObservacaoOCnaNF']=='S') {
            $mT005['T005_Ordem_Compra'] = ' OC: ' . mysql_real_escape_string($mT005['T005_Ordem_Compra']);
            $Observacao_Fiscal .= $mT005['T005_Ordem_Compra'];
        }
        $Observacao_Fiscal .= ';'; //Quebra linha
        
        if (!empty($mT005['T005_Cliente_Area']) && $mT005['T005_Cliente_Area'] != '' && $g['C031']['exibirObservacaoAreaClientenaNF'] == 'S') {
            $Observacao_Fiscal .= ' AREA: ' . $mT005['T005_Cliente_Area'] . ' ';
        }
        if ($mT005['T005_D013_Id'] > 0 && $g['C031']['exibirObservacaoContatonaNF'] == 'S') {
