    /**
     * excluirNFe
     *
     * @param int $T007_Id
     */
    public function excluirNFe($T007_Id)
    {
        //Scrip ainda não funcionando, verificar com Tiago. OS pausada
        $nT007_Id = isset($_REQUEST['T007_Id']) ? $_REQUEST['T007_Id'] : false;
        
        if (empty($nT007_Id)) {
            return '$nT007_Id não foi passado';
        }
        
        $cSql_C030 = mysql_query("select * from C030 where C030_C029_Id=90 and C030_Id_Perfil='$Perfil_Usuario' and C030_Acesso_Liberado='S'");
        if (mysql_num_rows($cSql_C030) == 0) {
            return "Acesso não autorizado!";
        }
        
        $cClausula = " select ";
        $cClausula .= " * ";
        $cClausula .= " from T007 ";
        $cClausula .= " where T007_Id='$nT007_Id' ";
        $cSql_T007 = mysql_query($cClausula);
        $mT007     = mysql_fetch_array($cSql_T007);
        
        if ($mT007['T007_Flag_ACP'] != '6') {
            return "O Tipo do documento não é NF-e. Verifique!!! Tipo: $mT007[T007_Flag_ACP]";
        }
        
        if (!empty($mT007['T007_Numero_Recibo_Nfe']) and $mT007['T007_Ambiente_NFe'] != 2) {
            return "Já existe um numero de RECIBO para essa nota./pSE JA EXISTE RECIBO, A NOTA ESTA SENDO PROCESSADA PELO SEFAZ E NAO PODE SER EXCLUIDA";
        }
        
        if (!empty($mT007['T007_Chave_Acesso_Nfe']) and $mT007['T007_Ambiente_NFe'] != 2) {
            return "Já existe uma chave de acesso para essa nota.";
        }
        
        if (!empty($mT007['T007_Numero_Protocolo_Nfe']) and $mT007['T007_Ambiente_NFe'] == 1) {
            return "Já existe um numero de protocolo para essa nota, VOCE NUNCA PODE EXCLUIR ESSA NOTA";
        }
        
        mysql_query("SET AUTOCOMMIT=0");
        mysql_query("START TRANSACTION");
        
        $cClausula = "delete from T001 where T001_T007_Id='$nT007_Id'";
        mysql_query($cClausula);
        $cErro = mysql_error();
        if (!empty($cErro)) {
            mysql_query("ROLLBACK");
            return "Erro: $cErro/p/p$cClausula";
        }
        
        $cClausula = "delete from T008 where T008_T007_Id='$nT007_Id'";
        mysql_query($cClausula);
        $cErro = mysql_error();
        if (!empty($cErro)) {
            mysql_query("ROLLBACK");
            return "Erro: $cErro/p/p$cClausula";
        }
        
        $cClausula = "update T127 set T127_Numero_Nota_Fiscal=concat('X',T127_Numero_Nota_Fiscal) where T127_Numero_Nota_Fiscal='$mT007[T007_Numero_Nota_Fiscal]' and T127_C004_Id='$mT007[T007_C004_Id]' and T127_D024_Id='$mT007[T007_D024_Id]'";
        mysql_query($cClausula);
        $cErro = mysql_error();
        if (!empty($cErro)) {
            mysql_query("ROLLBACK");
            return "Erro: $cErro/p/p$cClausula";
        }
        
        $cClausula = "delete from T002 where T002_T007_Id='$nT007_Id'";
        mysql_query($cClausula);
        $cErro = mysql_error();
        if (!empty($cErro)) {
            mysql_query("ROLLBACK");
            return "Erro: $cErro/p/p$cClausula";
        }
        
        $cClausula = "delete from T019 where T019_T007_Id='$nT007_Id'";
        mysql_query($cClausula);
        $cErro = mysql_error();
        if (!empty($cErro)) {
            mysql_query("ROLLBACK");
            return "Erro: $cErro/p/p$cClausula";
        }
        
        $cClausula = "delete from T007 where T007_Id='$nT007_Id'";
        mysql_query($cClausula);
        $cErro = mysql_error();
        if (!empty($cErro)) {
            mysql_query("ROLLBACK");
            return "Erro: $cErro/p/p$cClausula";
        }
        
        $cClausula = "update T005 set T005_Flag_Status=3, T005_Nome_Status = T005_Status_Pedido (T005_Flag_Status, 1) where T005_Id='{$mT007['T007_T005_Id']}'";
        mysql_query($cClausula);
        $cErro = mysql_error();
        if (!empty($cErro)) {
            mysql_query("ROLLBACK");
            return "Erro: $cErro/p/p$cClausula";
        } else {
            //Insere registros no histórico do pedido (T178)
            global $g;
            mysql_query("insert into T178(T178_T005_Id,T178_C007_Id,T178_Data,T178_Descricao,T178_Observacao) values ({$mT007['T007_T005_Id']},{$g['usuarioAtual']},CURRENT_TIMESTAMP(),'Aguardando Emissão NF','')");
        }
        
        mysql_query("COMMIT");
        echo "<script>parent.FecharTelaPendenciasContingencia();</script>";
        if ($mT007['T007_T005_Id'] > 0) {
            $cMensagem = ", pedido voltou ao status de emissao de notas.";
        }
        return true;
    }
    
    /**
     * retornarPedido
     *
     * @param int $T005_Id
     * @param int $T005_Flag_Status
     */
    public function retornarPedido($T005_Id, $T005_Flag_Status = 0)
    {
        global $g;
        
        //$T006 = mysql_query("select T006_Id from T006 where T006_Quantidade_Separacao>0 and T006_T005_Id='$T005_Id'");
        //if (mysql_num_rows($T006) > 0) {
            //return ("NÃO É POSSIVEL RETORNAR O PEDIDO PARA O VENDEDOR! <br> PEDIDO POSSUI QUANTIDADES SEPARADAS");
        //}

        $sqlPedidoTransporte = mysql_query("SELECT T005_Id FROM T005 WHERE T005_T005_Id_Origem = '{$T005_Id}' AND T005_Flag_Status != 8 AND T005_T224_Id > 0");
        if(mysql_num_rows($sqlPedidoTransporte) > 0){
            return "Existem itens faturados por outra empresa, para retornar o pedido é necessário cancelar o pedido gerado na outra empresa.";
        }

        if($g['C031']['statusInicialPedido'] == '3' || $g['C031']['desabilitarSeparacao'] == 'S'){
           mysql_query("DELETE FROM T238 WHERE T238_T005_Id = '{$T005_Id}'");
        }

        $sqlT005 = "select T005_Flag_Status,T005_Flag_Expedicao,T005_T224_Id from T005 where T005_Id='$T005_Id'";
        $cSql_T005 = mysql_query($sqlT005);
        $mT005     = mysql_fetch_array($cSql_T005);

        if (mysql_error()){
            log($sqlT175);
            return ("erro sql select T005 (ver log) retorna pedido (ven012.php), informe o suporte técnico.");
        }
        
        $T007 = mysql_query("SELECT T006_Id
                               FROM T006 
                          LEFT JOIN T008 ON T006_Id = T008_T006_Id
                          LEFT JOIN T007 ON T007_Id = T008_T007_Id
                              WHERE T006_T005_Id='{$T005_Id}'
                                AND T007_Flag_ACP = '8'
                                AND T007_Flag_Cancelada !='S' 
                                AND T007_Flag_Inutilizado !='S' 
                                AND (T007_Protocolo_Inutilizacao = '' OR T007_Protocolo_Inutilizacao IS NULL)");
        if (mysql_num_rows($T007) > 0) {
            return "Este pedido está vinculado a uma NFC-e, não pode ser retornado";
        }

        if($mT005['T005_T224_Id'] > 0){
            // Permitir voltar - marcelo de paula - 18-09-2014
            //return "Pedido de transferência gerado a partir de outra empresa, não pode ser retornado.";
        }

        // Quando for DAV (T005_Flag_Expedicao = 2) ele pode voltar mesmo estando em aguardando entrega
        if ($mT005['T005_Flag_Status'] == '4' && $mT005['T005_Flag_Expedicao'] != 2) {
            return ("Pedido já esta em AGUARDANDO ENTREGA!<br>Não pode ser alterado.<br>Apenas clique em CONTINUAR...");
        }
        
        if ($mT005['T005_Flag_Status'] == '8') {
            return ("Pedido esta CANCELADO!, não pode ser alterado");
        }
        
        // Caso status do pedido não tenha sido alterado, insere pedido no WMS
        if($mT005['T005_Flag_Status'] == $g['C031']['statusInicialPedido']) {
            require_once('bibliotecas/webservices/cyberlog/integracaoWMS.php');
            $WMS = new WMS();

            if($WMS->isEnabled() && !$WMS->isWarehouseUser() && $g['C031']['cyberlogLockOrder'] == 'S') {
                return "Pedido possuí tarefa em andamento, não pode ser alterado.<br>Contate o almoxarifado para viabilizar a liberação do pedido.";
            }
        }
        
        if($g['C031']['modeloExpedicao'] == 2){
			mysqli_query("UPDATE T005 SET T005_Flag_Almoxarifado='N',
                                          T005_Flag_Travar_Pedido=2,
                                          T005_Flag_Status='{$T005_Flag_Status}',
                                          T005_Flag_Reenviado_Almoxarifado='S',
                                          T005_Flag_Separacao_Liberar='N',
                                          T005_Flag_Almoxarifado='N'
                                    WHERE T005_Id='{$T005_Id}'");
        } else {
            mysqli_query("UPDATE T005 SET T005_Flag_Almoxarifado='N',
                                          T005_Flag_Travar_Pedido=2,
                                          T005_Flag_Status='{$T005_Flag_Status}',
                                          T005_Nome_Status = T005_Status_Pedido (T005_Flag_Status, 1),
                                          T005_Flag_Reenviado_Almoxarifado='S',
                                          T005_Flag_Reenviado_Almoxarifado_Lido='N',
                                          T005_Flag_Separacao='N',
                                          T005_Flag_Separacao_Liberar='N',
                                          T005_Flag_Almoxarifado='N',
                                          T005_Flag_Notificacao_Financeiro = ''
                                    WHERE T005_Id='{$T005_Id}'");
        }


        if (mysql_error()){
            return ("erro sql update T005 (ver log) retorna pedido (ven012.php), informe o suporte técnico.");
        }
        
        //Insere registros no histórico do pedido (T178)
        $sqlT178 = "insert into T178(T178_T005_Id,T178_C007_Id,T178_Data,T178_Descricao,T178_Observacao) values ({$T005_Id},{$g['usuarioAtual']},CURRENT_TIMESTAMP(),'Retornou pedido para o vendedor','')";

        mysql_query($sqlT178);

        if (mysql_error()){
            log($sqlT178);
            return ("erro sql update T178 (ver log) retorna pedido (ven012.php), informe o suporte técnico.");
        }

        // Atualiza notificação de análise de crédito
        //require_once('bibliotecas/classes/NOTIFICACOES.php');
        //$NOTIFICACOES= new NOTIFICACOES();
        //$NOTIFICACOES->liberarCredito(); // dois segundos - um pedido
        //$NOTIFICACOES->pedidoRetornoAlmoxarifado(); // um segundo - cinco pedidos
        //$NOTIFICACOES->pedidoCreditoLiberado(); // um segundo - 9 pedidos
        //$NOTIFICACOES->pedidoCreditoNaoLiberado(); // um segundo
        
        return true;
    }
    
    /**
     * retornarPedidoSeparacao
     *
     * @param int $T005_Id
     */
    public function retornarPedidoSeparacao($T005_Id)
    {
        global $g;
        $T006 = mysql_query("select T006_Id from T006 where T006_Quantidade_Separacao>0 and T006_T005_Id='$T005_Id'");
        
        if (mysql_num_rows($T006) > 0) {
            // return "NÃO É POSSIVEL RETORNAR O PEDIDO PARA O VENDEDOR! <br> PEDIDO POSSUI QUANTIDADES SEPARADAS";
        }
        
        $cSql_T005 = mysql_query("select * from T005 where T005_Id='$T005_Id'");
        $mT005     = mysql_fetch_array($cSql_T005);
        
        if ($mT005['T005_Flag_Status'] == '4') {
            return "Pedido já esta em AGUARDANDO ENTREGA!<br>Não pode ser alterado.<br>Apenas clique em CONTINUAR...";
        }
        
        if ($mT005['T005_Flag_Status'] == '8') {
            return "Pedido esta CANCELADO!, não pode ser alterado";
        }
        // T005_Flag_Separacao='S' and T005_Flag_Status='21' and T005_Flag_Separacao_Liberar='N' and T005_Flag_Expedicao=2
        
        mysql_query("update T005 set
                                T005_Flag_Travar_Pedido=2,
                                T005_Flag_Status=21,
                                T005_Nome_Status = T005_Status_Pedido (T005_Flag_Status, 1),
                                T005_Flag_Reenviado_Almoxarifado='S',
                                T005_Flag_Separacao='S',
                                T005_Flag_Separacao_Liberar='N',
                                T005_Flag_Almoxarifado='N'
                          where T005_Id='{$T005_Id}'");
        
        //Insere registros no histórico do pedido (T178)
        mysql_query("insert into T178(T178_T005_Id,T178_C007_Id,T178_Data,T178_Descricao,T178_Observacao) values ({$T005_Id},{$g['usuarioAtual']},CURRENT_TIMESTAMP(),'Retornou pedido para separação','')");
        
        return true;
    }
    
    /**
     * confirmarEntrega
     *
     * @param int $T005_Id
     */
    public function confirmarEntrega($T005_Id)
    {
        global $g;
        mysql_query("START TRANSACTION");
        
        $T005  = mysql_query("SELECT T005_Flag_ACP,
                                     T007_Id,
                                     T007_Flag_Expedicao,
                                     T005_Id 
                                FROM T005 
                           LEFT JOIN T007 ON T007_T005_Id = T005_Id AND T007_Flag_Cancelada != 'S' 
                               WHERE T005_Id = '{$T005_Id}'");
        $mT005 = mysql_fetch_assoc($T005);
        
        // Apenas para Cupom Fiscal ou um cupom que virou NF (T007_Flag_Expedicao = 2)
        //if ($mT005['T007_Flag_ACP'] == 4) { // || $mT005['T007_Flag_Expedicao'] == 2) {

        $travaSemSeparacao = true;
            
        $tipoEmitido = ($mT005['T005_Flag_ACP'] == 4) ? 'CF' : 'NF';
            
        $cSql_T007 = mysql_query("SELECT  *
                                    FROM T007
                               LEFT JOIN D089 ON D089_Id=T007_D089_Id                          
                               LEFT JOIN D024 ON D024_Id=T007_D024_Id
                               LEFT JOIN D006 ON D006_Id=T007_D006_Id
                                   WHERE T007_Id='{$mT005['T007_Id']}'");
        $mT007  = mysql_fetch_array($cSql_T007);
            
        $resT008 = mysql_query("SELECT *,
                                       D009_Custo_Unitario(D009_Id) Custo_Unitario,
                                       (D009_Custo_Unitario(D009_Id)*T008_Quantidade) Custo_Total,
                                       D009_Local(D009_Id,1) Local_1
                                  FROM T008
                              LEFT JOIN T007 ON T007_Id=T008_T007_Id
                              LEFT JOIN D009 ON D009_Id=T008_D009_Id
                              LEFT JOIN D049 ON D049_Id=D009_D049_Id
                              LEFT JOIN D001 ON D001_Id=D049_D001_Id
                              LEFT JOIN D006 ON D006_Id=T008_D006_Id
                              LEFT JOIN T001 ON T008_Id=T001_T008_Id
                                  WHERE T008_T007_Id='{$mT005['T007_Id']}'
                                    AND T008_Quantidade>0
                                    AND T001_Id IS NULL
                               ORDER BY Local_1,T008_Id");

        $cErro   = mysql_error();
        if (!empty($cErro)) {
            mysql_query("ROLLBACK");
            return "Erro: $cErro";
        }

        if(mysql_num_rows($resT008) <= 0){
            $travaSemSeparacao = false;
        }

        while ($mT008 = mysql_fetch_array($resT008)) {
            // A separação precisa ser encontrada para cada item, e não somente
            // para algum item do pedido.
