                    $cErro = mysql_error();
                    mysql_query("ROLLBACK");
                    return "Erro ao consultar a separação do item {$mT008['T008_Id']}: {$cErro}";
                }

                while ($rowT238 = mysql_fetch_assoc($resT238)) {
