                    $cClausula .= " '{$mT008['T007_Id']}', ";
                    $cClausula .= " '{$mT008['T008_D009_Id']}', ";
                    $cClausula .= " '{$mT008['T008_C004_Id']}', ";
                    $cClausula .= " '{$mT008['T008_D006_Id']}', ";
                    //$cClausula .= " '$mT066[T066_Id]', ";
                    //$cClausula .= " '$mT008[T008_T066_Id]', ";
                    $cClausula .= " '{$rowT238['T066_Id']}', ";
                    $cClausula .= " '{$mT008['T008_Codigo_Produto']}', ";
                    $cClausula .= " current_date(), ";
                    $cClausula .= " '{$tipoEmitido}-{$mT007['T007_Numero_Nota_Fiscal']}', ";
                    //$cClausula .= " '$mT008[T008_Quantidade]', ";
                    $cClausula .= " '{$rowT238['T238_Quantidade_Separacao']}', ";
                    $cClausula .= " '$Flag_Operacao_Historico', ";
                    $cClausula .= " '{$mT008['T008_Valor_Preco_Unitario']}', ";
                    $cClausula .= " '', ";
                    $cClausula .= " '{$mT008['Custo_Unitario']}', ";
                    $cClausula .= " '0', ";
                    $cClausula .= " '{$mT008['D006_Flag_MMF']}', ";
                    $cClausula .= " '{$mT008['D006_Flag_Atualiza_Custo']}', ";
                    $cClausula .= " '{$tmpD004_Id}' ";
                    $cClausula .= " )";
                    //file_put_contents('/tmp/log', $cClausula . "\n", FILE_APPEND);
                    if (!mysql_query($cClausula)) {
                        $cErro = mysql_error();
                        mysql_query("ROLLBACK");
                        return "Erro ao gravar o histórico de estoque do item {$mT008['T008_Id']}: {$cErro}";
                    }
                }
            } else {
                // baixa já foi feita no Cupom Fiscal
                $travaSemSeparacao = false;
            }

            if ($travaSemSeparacao) {
                mysql_query("ROLLBACK");
                return "Item {$mT008['T008_Id']} não possui registro de separação para gerar o histórico de estoque. O pedido permaneceu no status atual.";
            }
            
            // Executa reprocessa histórico do produto
            require_once("bibliotecas/classes/CAD002.php");
            $CAD002 = new CAD002();
            $retorno = $CAD002->D001_reprocessa_historico(0, $mT008['T008_D009_Id'], 50);
            if ($retorno !== true) {
                mysql_query("ROLLBACK");
                return "Erro ao reprocessar o histórico de estoque do item {$mT008['T008_Id']}: {$retorno}";
            }
        }

        if ($travaSemSeparacao) {
            mysql_query("ROLLBACK");
            return "Existem itens sem registro no histórico de estoque (T001). O pedido permaneceu no status atual.";
        }
        //}
        
        $sqlUpdtT005 = <<<SQL
            UPDATE T005 SET T005_Flag_Status = 5, T005_Nome_Status = T005_Status_Pedido(T005_Flag_Status, 1) WHERE T005_Id = '{$T005_Id}'
        SQL;

        if (!mysql_query($sqlUpdtT005)) {
            $cErro = mysql_error();
            mysql_query("ROLLBACK");
            return "Erro ao atualizar o pedido para coletado: {$cErro}";
        }

        //Insere registros no histórico do pedido (T178)
        $sqlInsT178 = <<<SQL
            INSERT INTO T178 (
                T178_T005_Id,
                T178_C007_Id,
                T178_Data,
                T178_Descricao,
                T178_Observacao
            ) VALUES (
                '{$T005_Id}',
                '{$g['usuarioAtual']}',
                CURRENT_TIMESTAMP(),
                'Coletado',
                ''
            )
        SQL;
        if (!mysql_query($sqlInsT178)) {
            $cErro = mysql_error();
            mysql_query("ROLLBACK");
            return "Erro ao gravar o histórico de coleta do pedido: {$cErro}";
        }
        
        //mysql_query("ROLLBACK");
        //return "teste";
        
        if (!mysql_query("COMMIT")) {
            $cErro = mysql_error();
            mysql_query("ROLLBACK");
            return "Erro ao confirmar a coleta do pedido: {$cErro}";
        }
        return true;
    }
    
    /**
