        $T005_Transportadora_Placa_Veiculo = str_replace("-", "", $T005_Transportadora_Placa_Veiculo);
        $T005_Transportadora_Placa_Veiculo = str_replace(" ", "", $T005_Transportadora_Placa_Veiculo);

        log("variáveis fomularioNota");
        log("************************************************");
        log("T005_Id: ".$T005_Id);
        log("D024_Nome_Empresa: ".$D024_Nome_Empresa);
        log("T005_Valor_Total: ".$T005_Valor_Total);
        log("D024_Endereco: ".$D024_Endereco);
        log("Cidade: ".$Cidade);
        log("T005_Transportadora_Placa_Veiculo: ".$T005_Transportadora_Placa_Veiculo);
        log("Consulta_T005_D022_Id: ".$Consulta_T005_D022_Id);
        log("T005_Valor_Frete: ".$T005_Valor_Frete);
        log("T005_Peso_Liquido: ".$T005_Peso_Liquido);
        log("T005_Peso_Bruto: ".$T005_Peso_Bruto);
        log("T005_Valor_Despesas_Acessorias: ".$T005_Valor_Despesas_Acessorias);
        log("T005_Data_Saida: ".$T005_Data_Saida);
        log("Flag_ACP: ".$Flag_ACP);
        log("T005_Observacao: ".$T005_Observacao);
        log("T005_Observacao_Nota_Fiscal: ".$T005_Observacao_Nota_Fiscal);
        log("T005_D022_Id: ".$T005_D022_Id);
        log("T005_Estado_Veiculo: ".$T005_Estado_Veiculo);
