        log("T005_D036_Id: ".$T005_D036_Id);
        log("T005_Quantidade_Volumes: ".$T005_Quantidade_Volumes);
        log("T005_Especie: ".$T005_Especie);
        log("T005_Marca: ".$T005_Marca);
        log("T005_Numero_Caixas: ".$T005_Numero_Caixas);
        log("Numero_Nota: ".$Numero_Nota);
        log("************************************************");
        
        if ($T005_Peso_Liquido > $T005_Peso_Bruto) {
            return "O peso líquido é maior que o peso bruto. Informe corretamente.";
        }

        if($T005_Flag_Frete != 9 && $T005_D022_Id <= 0) {
            return "O tipo do frete selecionado exige que seja informado uma transportadora, verifique os dados e tente novamente.";
        }
        
        $cT005 = " select *
                         from T005
                    left join D024 on D024_Id=T005_D024_Id
                    left join D018 on D018_Id=D024_D018_Id
                    left join D020 on D020_Id=D024_D020_Id
                    left join D006 on D006_Id=T005_D006_Id
                        where T005_Id='{$T005_Id}'";
        
        $Sql_T005 = mysql_query($cT005);
        $mT005    = mysql_fetch_array($Sql_T005);


        $T006=mysql_query("SELECT ROUND(SUM(T006_Valor_Total_Frete),2) AS FreteProdutos FROM T006 WHERE T006_T005_Id = '{$T005_Id}'");
        $mT006=mysql_fetch_array($T006);

        //Verifica o frete dos produtos caso obrigatório rateio do frete quando por conta do emitente
        if($mT005['T005_Valor_Frete'] != $mT006['FreteProdutos'] && $g['C031']['ratearFreteVendaNoCusto'] == 'S' && $mT005['T005_Flag_Frete'] == '0'){
