        }
        
        $C004  = mysql_query("select * from C004 where C004_Id='{$mT005['T005_C004_Id']}'");
        $mC004 = mysql_fetch_array($C004);
        
        $Consulta_T005_D022_Id          = strtomaiusculo($Consulta_T005_D022_Id);
        $T005_Valor_Frete               = formata_valor_gravar($T005_Valor_Frete, 3);
        $T005_Valor_Despesas_Acessorias = formata_valor_gravar($T005_Valor_Despesas_Acessorias, 3);
        $T005_Data_Saida                = Troca_Data_amd($T005_Data_Saida);
        
        //Verifica se o portador é boleto, caso seja deve ter uma conta ligada a ele
        $sqlT090 = mysql_query("SELECT D027_Flag_Boleto,D027_D007_Id FROM T090 LEFT JOIN D027 ON D027_Id = T090_D027_Id WHERE T090_T005_Id = '{$T005_Id}'");
        while ($T090 = mysql_fetch_array($sqlT090)) {
