                return "O portador \"".$mT090['D027_Portador']."\" está com a conta bancária inativa. Por favor verifique com o setor financeiro";
            }
        }
        
        if ($g['c020']['C020_Caixa_Cupom_Fiscal'] == 'N' and $Flag_ACP == 4) {
            return 'Opção de cupom fiscal não esta habilitada.';
        }
        
        if ($g['c020']['C020_NFe_Habilitada'] == 'S' and $Flag_ACP == 1) {
            return 'Você esta tentando emitir uma nota fiscal normal e a opção de NF-e esta habilitada para esta empresa. Verifique por favor';
        }
        
        $mLinhas_Observacao = explode("\n", $T005_Observacao);
        $Linhas_Observacao  = count($mLinhas_Observacao);
        if ($Flag_ACP == 1) {
            for ($x = 0; $x < $Linhas_Observacao; $x++) {
                if (strlen($mLinhas_Observacao[$x]) > 80) {
                    return 'Observação Cliente não pode ultrapassar 80 caracteres por linha! Pedido não pode ser liberado';
                }
            }
            if ($Linhas_Observacao > 4) {
                return 'Observação Cliente não pode ultrapassar 4 linhas! Pedido não pode ser liberado';
            }
        }
        
        $mLinhas_Observacao = explode("\n", $T005_Observacao_Nota_Fiscal);
        $Linhas_Observacao  = count($mLinhas_Observacao);
        if ($Flag_ACP == 1) {
            for ($x = 0; $x < $Linhas_Observacao; $x++) {
                if (strlen($mLinhas_Observacao[$x]) > 80) {
                    return 'Observação Fiscal não pode ultrapassar 80 caracteres por linha! Pedido não pode ser liberado';
                }
            }
        }
        
        if ($Flag_ACP == 6) {
            if (strlen($T005_Observacao) > 256) {
                //return 'Observação cliente ultrapassou 256 caracteres, diminua o tamanho da observação cliente. O Total de caracteres neste campo é de:'.strlen($T005_Observacao);
            }
            
            if (strlen($mC004['C004_Observacao_Fiscal'] . $T005_Observacao_Nota_Fiscal) > 256) {
                //return 'Observação fiscal ultrapassou 256 caracteres, diminua o tamanho da observação fiscal. O Total de caracteres neste campo é de:'.strlen($mC004['C004_Observacao_Fiscal'].$T005_Observacao_Nota_Fiscal);
            }
        }
        
        $cSql_T006_Diferido = mysql_query("select T006_Id
                                             from T006
                                            where T006_T005_Id='{$T005_Id}'
                                              and T006_Percentual_Reducao_ICMS>0");
        if (mysql_num_rows($cSql_T006_Diferido) > 0) {
            if ($Linhas_Observacao > 3 && $Flag_ACP == 1) {
                return 'Observação Fiscal não pode ultrapassar 3 linhas! Pedido não pode ser liberado';
            }
        } else {
            if ($Linhas_Observacao > $mC004['C004_Linhas_Obs_Fiscal'] && !empty($mC004['C004_Linhas_Obs_Fiscal']) && $Flag_ACP == 1) {
                return "Observação Fiscal não pode ultrapassar " . $mC004['C004_Linhas_Obs_Fiscal'] . " linhas! Pedido não pode ser liberado";
            }
        }
        
        if ($T005_D022_Id > 0) {
            $cClausula = "select * from D022 left join D020 on D020_Id=D022_D020_Id left join D018 on D018_Id=D022_D018_Id where D022_Id='{$T005_D022_Id}'";
            $cSql_D022 = mysql_query($cClausula);
            $mD022     = mysql_fetch_array($cSql_D022);
