                $T005_D022_Id = 0;
            } else {
                $Consulta_T005_D022_Id = $mD022['D022_Nome_Empresa'];
            }
        }
        
        if (!empty($Consulta_T005_D022_Id) or $T005_D022_Id > 0) {
            if (!empty($T005_Transportadora_Placa_Veiculo)) {
                if (strlen($T005_Transportadora_Placa_Veiculo) != 7) {
                    return "Placa do Veiculo esta incorreta. Caso tenha preenchido, não coloque hífen (-) ou espaço";
                }
                if (empty($T005_Estado_Veiculo)) {
                    return "Informe a UF do veículo";
                }
            }
        } else {
            if (!empty($T005_Transportadora_Placa_Veiculo)) {
                return "Foi informado a placa do veículo, porém, não foi informado a transportadora. Se foi apenas preenchido o nome do transportador, então não deve ser preenchido a placa do veículo, caso contrario, cadastre a transportadora";
            }
            
        }
        
        $T005_Observacao             = mysql_real_escape_string($T005_Observacao);
        $T005_Observacao_Nota_Fiscal = mysql_real_escape_string($T005_Observacao_Nota_Fiscal);
        $Consulta_T005_D022_Id       = mysql_real_escape_string($Consulta_T005_D022_Id);
        
        $cClausula = " update T005 set ";
