        $cClausula .= " T005_Estado_Veiculo='{$T005_Estado_Veiculo}',";
        $cClausula .= " T005_Flag_Frete='{$T005_Flag_Frete}',";
        $cClausula .= " T005_Valor_Frete='{$T005_Valor_Frete}',";
        $cClausula .= " T005_D022_Id='{$T005_D022_Id}',";
        $cClausula .= " T005_D036_Id='{$T005_D036_Id}',";
        $cClausula .= " T005_Observacao='{$T005_Observacao}',";
        $cClausula .= " T005_Data_Saida='{$T005_Data_Saida}',";
        //$cClausula .= " T005_Flag_Revenda_Consumidor='{$T005_Flag_Revenda_Consumidor}',";
        $cClausula .= " T005_Observacao_Nota_Fiscal='{$T005_Observacao_Nota_Fiscal}',";
        // esta � a observacao almoxarifaado   $cClausula .= " T005_Observacao_1='$T005_Observacao_1',";
        $cClausula .= " T005_Quantidade_Volumes='{$T005_Quantidade_Volumes}',";
        $cClausula .= " T005_Especie='{$T005_Especie}',";
        $cClausula .= " T005_Marca='{$T005_Marca}',";
        $cClausula .= " T005_Numero_Caixas='{$T005_Numero_Caixas}',";
        $cClausula .= " T005_Peso_Liquido='{$T005_Peso_Liquido}',";
        $cClausula .= " T005_Peso_Bruto='{$T005_Peso_Bruto}',";
        $cClausula .= " T005_Valor_Despesas_Acessorias='{$T005_Valor_Despesas_Acessorias}'";
        $cClausula .= " where T005_Id='{$T005_Id}'";
        log("***UPDATE T005 NO FOMULARIO NOTA*****");
        log($cClausula);
        mysql_query($cClausula);
        $cErro = mysql_error();
        if (!empty($cErro)) {
            $retorno = "Clausula: " . $cClausula . "<br />";
            $retorno .= "ERRO: " . $cErro;
            mysql_query("ROLLBACK");
            return $retorno;
        }
        
        //-- EFETUA TOTALIZACAO DOS DADOS
        $cSql_T006 = mysql_query("select T006_Id from T006 where T006_T005_Id='$T005_Id' order by T006_Id");
        while ($mT006 = mysql_fetch_array($cSql_T006)) {
            mysql_query("call T006_Gravar_Totalizacao_4('{$mT006['T006_Id']}')");
            
            //zerando preço bruto para empresas que usam preço líquido
            if ($g['C031']['precopadraoVendaProduto'] !== 'bruto') {
                mysqli_query("UPDATE T006 SET T006_Valor_Preco_Bruto='0.00' WHERE T006_Id='{$mT006['T006_Id']}'");
            }
        }
        //mysql_query("call T005_Gravar_Totalizacao_4('{$T005_Id}')");
        
        mysqli_query("update T005 set T005_Flag_ACP='$Flag_ACP' where T005_Id='$T005_Id'");
        log("****UPDATE T005 -2 NO FOMULARIO NOTA: ");
        log("update T005 set T005_Flag_ACP='$Flag_ACP' where T005_Id='$T005_Id'");
        if ($Flag_ACP == '5') {
            if (empty($Numero_Nota)) {
                return 'Número da nota não informado';
            }
            
            $sql = mysql_query("select * from T007 where T007_Numero_Nota_Fiscal='$Numero_Nota' and T007_Flag_ACP='5'");
            
            if (mysql_num_rows($sql) > 0) {
                return "Já existe uma nota fiscal D1 com o número" . $Numero_Nota;
            }
            
            $cSql = mysql_query("update T005 set T005_Numero_Nota_Manual='{$Numero_Nota}' where T005_Id='{$T005_Id}'");
            
        }
        
        if ($Flag_ACP == '7') {
            if (empty($Numero_Nota)) {
                return 'Número da nota não informado';
            }
            
            $sql = mysql_query("select * from T007 where T007_Numero_Nota_Fiscal='{$Numero_Nota}' and T007_Flag_ACP='7'");
            
            if (mysql_num_rows($sql) > 0) {
                return "Já existe uma nota fiscal eletrônica de serviço com o número" . $Numero_Nota;
            }
            
            $cSql = mysql_query("update T005 set T005_Numero_Nota_Manual='{$Numero_Nota}' where T005_Id='{$T005_Id}'");
            
        }
        
        if ($Flag_ACP == '2') {
            $cSql = mysql_query("update T005 set T005_Flag_Status='4',T005_Nome_Status = T005_Status_Pedido (T005_Flag_Status, 1),T005_Flag_Situacao=' ' where T005_Id='{$T005_Id}'");
            
            //Insere registros no histórico do pedido (T178)
            //mysql_query("insert into T178(T178_T005_Id,T178_C007_Id,T178_Data,T178_Descricao,T178_Observacao) values ({$T005_Id},{$g['usuarioAtual']},CURRENT_TIMESTAMP(),'Aguardando Coleta Transportadora','')");
        }
        
        if($g['C031']['geracaoNotaEmEtapas'] == 'S'){
            $retornoGerarNF = $this->gerarNotaFiscal($form, $mD022);
        } else {
            $retornoGerarNF = $this->xgerarNotaFiscal($form, $mD022);
        }
        
        if (!$retornoGerarNF) {
            $cSql = mysql_query("update T005 set T005_Flag_Status='4',T005_Nome_Status = T005_Status_Pedido (T005_Flag_Status, 1),T005_Flag_Situacao=' ' where T005_Id='{$T005_Id}'");
            //Insere registros no histórico do pedido (T178)
            //mysql_query("insert into T178(T178_T005_Id,T178_C007_Id,T178_Data,T178_Descricao,T178_Observacao) values ({$T005_Id},{$g['usuarioAtual']},CURRENT_TIMESTAMP(),'Aguardando Coleta Transportadora','')");
            return true;
        } else {
            return $retornoGerarNF;
        }
    }
    
    /**
     * gerarNotaFiscal
     *
     * @param Form $form
     * @param array $mD022
     */
    public function xgerarNotaFiscal($form, $mD022)
    {
        global $g, $mT005, $mD024, $mT090, $mLetras, $T005_D024_Id_Contas, $mT007, $T005_Id, $Valor_Comissao_Usuario, $Valor_Base_Comissao_Titulo, $Valor_Comissao, $Valor_Comissao_Representante, $Valor_Comissao_Externo, $mVencimento, $total_Parcelas, $Observacao_Fiscal_Produto, $mT006;
        global $confUsuario;

