    /**
     * est012DividirPedido
     *
     * @param int $T005_Id_Antigo
     * @param int $C004_Id_Novo
     */
    public function est012DividirPedido($T005_Id_Antigo, $C004_Id_Novo)
    {
        global $g, $novoT005_Id;
        
        require_once('bibliotecas/classes/VEN001.php');
        $VEN001 = new VEN001();
        require_once('bibliotecas/classes/VEN002.php');
        $VEN002 = new VEN002();
        
        mysql_query("SET AUTOCOMMIT=0");
        mysql_query("START TRANSACTION");
        
        // seleciona o cabeçalho do pedido para inserir um cópia dele com o novo C004 
        $sqlT005    = "SELECT * FROM T005 WHERE T005_Id='{$T005_Id_Antigo}'";
        $resultT005 = mysql_query($sqlT005);
        $mLinhaT005  = mysql_fetch_array($resultT005);
        
        $T005  = mysql_query("SELECT * FROM T005 WHERE T005_Id='{$T005_Id_Antigo}'");
        $mT005 = mysql_fetch_assoc($T005);
        
        // Buscando a CFOP para o cabeçalho do orçamento
        $D006_Id = $VEN001->retornaCFOP($linhaT005['T005_D024_Id'], false, $C004_Id_Novo);
        
        $T005_Id_Antigo = $mT005['T005_Id'];
        $campos         = "";
        $valores        = "";
        foreach ($mT005 as $key => $value) {
            if ($key == 'T005_Id') {
                continue;
            } elseif ($key == "T005_D006_Id") {
                $campos .= $key . ", ";
                $valores .= "'{$D006_Id}',";
            } elseif ($key == "T005_C004_Id") {
                $campos .= $key . ", ";
                $valores .= "'{$C004_Id_Novo}',";
            } elseif ($key == "T005_Flag_Dividido") {
                $campos .= $key . ", ";
                $valores .= "'S',";
            } else {
                $campos .= $key . ", ";
                $valores .= "'" . mysql_real_escape_string($value) . "',";
            }
        }
        $campos  = trim($campos, ', ');
        $valores = trim($valores, ',');
        $insT005 = "INSERT INTO T005 ({$campos}) VALUES ({$valores})";
        $resT005 = mysql_query($insT005);
        if (!$resT005) {
            mysql_query("ROLLBACK");
            return "Erro 1: " . mysql_error(). "SQL: ".$insT005;
        }
        $novoT005_Id = $g['mysqlLastId'];
        
        // Seleciona os itens do pedido para ver se existe algum marcado
        $sqlT006    = "SELECT * FROM T006 WHERE T006_T005_Id='{$T005_Id_Antigo}' AND (T006_Flag_Dividir='S' OR T006_Quantidade_Dividir > 0);";
        $resultT006 = mysql_query($sqlT006);
        
        // Usa a SQL da T006 feita no início do método para fazer update dos itens que foram selecionados para gerar outro pedido 
        while ($linhaT006 = mysql_fetch_assoc($resultT006)) {
            
            // Caso seja para dividr o pedido conforme a quantidade, entra no IF. senão, no ELSE
            if ($linhaT006['T006_Quantidade_Dividir'] > 0) {
                $campos  = "";
                $valores = "";
                
                // Caso a quantidade á dividir seja igual a quantidade do pedido, será feito um update mudando o item do pedido para o no cabeçalho
                if ($linhaT006['T006_Quantidade_Dividir'] == $linhaT006['T006_Quantidade']) {
                    
                    // Daqui para baixo (dentro desse IF) faz o prcesso normal de alteração de cabeçalho do pedido
                    
                    $sqlD049    = "SELECT D009_D049_Id FROM D009 WHERE D009_Id='{$linhaT006['T006_D009_Id']}'";
                    $resultD049 = mysql_query($sqlD049);
                    $linhaD049  = mysql_fetch_array($resultD049);
                    $erroSQL    = mysql_error();
                    if (!empty($erroSQL)) {
                        mysql_query("ROLLBACK");
                        return '2...' . $erroSQL;
                    }
                    /**
                     * Buscando o D009 correto para a empresa selecionada.
                     */
                    $sqlD009    = "SELECT D009_Id FROM D009 WHERE D009_D049_Id='{$linhaD049['D009_D049_Id']}' AND D009_C004_Id='{$C004_Id_Novo}'";
                    $resultD009 = mysql_query($sqlD009);
                    $linhaD009  = mysql_fetch_array($resultD009);
                    $erroSQL    = mysql_error();
                    if (!empty($erroSQL)) {
                        mysql_query("ROLLBACK");
                        return '3' . $erroSQL;
                    }
                    if (empty($linhaD009['D009_Id'])) {
                        mysql_query("ROLLBACK");
                        return 'D009_Id não encontrado';
                    }
                    
                    /**
                     * Buscando a CFOP correta para cada item
                     */
                    $D006_Id = $VEN001->retornaCFOP($linhaT005['T005_D024_Id'], $linhaD009['D009_Id'], $C004_Id_Novo, $linhaT006['T006_Flag_Destino_Produto'], false, false, $linhaT005['T005_C004_Id_Origem'], $linhaT005['T005_C004_Id_Estoque']);
                    
                    /**
                     * Faz update nos itens do pedido alterando o T005, C004 (id da empresa nova) e o D009 da nova empresa
                     */
                    $upT006 = "UPDATE T006 SET T006_T005_Id='{$novoT005_Id}', T006_C004_Id='{$C004_Id_Novo}', T006_Flag_Dividir='N', T006_D006_Id='{$D006_Id}', T006_D009_Id='{$linhaD009['D009_Id']}', T006_Quantidade_Dividir=0 WHERE T006_Id='{$linhaT006['T006_Id']}'";
                    mysql_query($upT006);
                    $erroSQL = mysql_error();
                    if (!empty($erroSQL)) {
                        mysql_query("ROLLBACK");
                        return '4' . $erroSQL;
                    }
                    
                } else { // Caso a quantidade seja menor que a quantidade anterior, é feito um insert com o novo pedido e um update no item antigo diminuindo a quantidade
                    
                    $quantidadeAntiga = $linhaT006['T006_Quantidade'] - $linhaT006['T006_Quantidade_Dividir'];
                    $quantidadeNova   = $linhaT006['T006_Quantidade_Dividir'];
                    
                    // Atualizando a quantidade do item antigo.
                    $upT006Antigo = mysql_query("UPDATE T006 SET T006_Quantidade='{$quantidadeAntiga}', T006_Quantidade_Dividir='', T006_Flag_Dividir='N' WHERE T006_Id='{$linhaT006['T006_Id']}'");
                    
                    $sqlD049    = "SELECT D009_D049_Id FROM D009 WHERE D009_Id='{$linhaT006['T006_D009_Id']}'";
                    $resultD049 = mysql_query($sqlD049);
                    $linhaD049  = mysql_fetch_array($resultD049);
                    $erroSQL    = mysql_error();
                    if (!empty($erroSQL)) {
                        mysql_query("ROLLBACK");
                        return '2...' . $erroSQL;
                    }
                    /**
                     * Buscando o D009 correto para a empresa selecionada.
                     */
                    $sqlD009    = "SELECT D009_Id FROM D009 WHERE D009_D049_Id='{$linhaD049['D009_D049_Id']}' AND D009_C004_Id='{$C004_Id_Novo}'";
                    $resultD009 = mysql_query($sqlD009);
                    $linhaD009  = mysql_fetch_array($resultD009);
                    $erroSQL    = mysql_error();
                    if (!empty($erroSQL)) {
                        mysql_query("ROLLBACK");
                        return '3' . $erroSQL;
                    }
                    if (empty($linhaD009['D009_Id'])) {
                        mysql_query("ROLLBACK");
                        return 'D009_Id não encontrado';
                    }
                    
                    /**
                     * Buscando a CFOP correta para cada item
                     */
                    $D006_Id = $VEN001->retornaCFOP($linhaT005['T005_D024_Id'], $linhaD009['D009_Id'], $C004_Id_Novo, $linhaT006['T006_Flag_Destino_Produto'], false, false, $linhaT005['T005_C004_Id_Origem'], $linhaT005['T005_C004_Id_Estoque']);
                    
                    // Selecionando todos os dados do T006 atual para fazer um insert do novo T006 com a quantidade nova
                    foreach ($linhaT006 as $key => $value) {
                        if ($key == 'T006_Id') {
                            continue;
                        } elseif ($key == "T006_T005_Id") {
                            $campos .= $key . ", ";
                            $valores .= "'" . mysql_real_escape_string($novoT005_Id) . "',";
                        } elseif ($key == "T006_C004_Id") {
                            $campos .= $key . ", ";
                            $valores .= "'" . mysql_real_escape_string($C004_Id_Novo) . "',";
                        } elseif ($key == "T006_Quantidade") {
                            $campos .= $key . ", ";
                            $valores .= "'" . mysql_real_escape_string($quantidadeNova) . "',";
                        } elseif ($key == "T006_D006_Id") {
                            $campos .= $key . ", ";
                            $valores .= "'" . mysql_real_escape_string($D006_Id) . "',";
                        } elseif ($key == "T006_C004_Id_Estoque") {
                            $campos .= $key . ", ";
                            $valores .= "NULL,";
                        } elseif ($key == "T006_D009_Id") {
                            $campos .= $key . ", ";
                            $valores .= "'" . mysql_real_escape_string($linhaD009['D009_Id']) . "',";
                        } else {
                            $campos .= $key . ", ";
                            $valores .= "'" . mysql_real_escape_string($value) . "',";
                        }
                    }
                    $campos  = trim($campos, ', ');
                    $valores = trim($valores, ',');
                    
                    // Monta o Insert e executa
                    $insT006 = "INSERT INTO T006 ({$campos}) VALUES ({$valores})";
                    $resT006 = mysql_query($insT006);
                    $erroSQL = mysql_error();
                    if (!empty($erroSQL)) {
                        mysql_query("ROLLBACK");
                        return '1.1...' . $erroSQL;
                    }
                    $T006_Id = mysql_insert_id();
                    mysql_query("update T006 set T006_Quantidade_Dividir=0 where T006_Id='{$T006_Id}'");
                }
            } else {
                $sqlD049    = "SELECT D009_D049_Id FROM D009 WHERE D009_Id='{$linhaT006['T006_D009_Id']}'";
                $resultD049 = mysql_query($sqlD049);
                $linhaD049  = mysql_fetch_array($resultD049);
                $erroSQL    = mysql_error();
                if (!empty($erroSQL)) {
                    mysql_query("ROLLBACK");
                    return '2...' . $erroSQL;
                }
                /**
                 * Buscando o D009 correto para a empresa selecionada.
                 */
                $sqlD009    = "SELECT D009_Id FROM D009 WHERE D009_D049_Id='{$linhaD049['D009_D049_Id']}' AND D009_C004_Id='{$C004_Id_Novo}'";
                $resultD009 = mysql_query($sqlD009);
                $linhaD009  = mysql_fetch_array($resultD009);
                $erroSQL    = mysql_error();
                if (!empty($erroSQL)) {
                    mysql_query("ROLLBACK");
                    return '3' . $erroSQL;
                }
                if (empty($linhaD009['D009_Id'])) {
                    mysql_query("ROLLBACK");
                    return 'D009_Id não encontrado';
                    
                }
                
                /**
                 * Buscando a CFOP correta para cada item
                 */
                $D006_Id = $VEN001->retornaCFOP($linhaT005['T005_D024_Id'], $linhaD009['D009_Id'], $C004_Id_Novo, $linhaT006['T006_Flag_Destino_Produto'], false, false, $linhaT005['T005_C004_Id_Origem'], $linhaT005['T005_C004_Id_Estoque']);
                
                /**
                 * Faz update nos itens do pedido alterando o T005, C004 (id da empresa nova) e o D009 da nova empresa
                 */
                $upT006 = "UPDATE T006 SET T006_T005_Id='{$novoT005_Id}', T006_C004_Id='{$C004_Id_Novo}', T006_Flag_Dividir='N', T006_D006_Id='{$D006_Id}', T006_D009_Id='{$linhaD009['D009_Id']}' WHERE T006_Id='{$linhaT006['T006_Id']}'";
                mysql_query($upT006);
                $erroSQL = mysql_error();
                if (!empty($erroSQL)) {
                    mysql_query("ROLLBACK");
                    return '4' . $erroSQL;
                }
            }
            //mysql_query("call T006_Gravar_Totalizacao_4('{$linhaT006['T006_Id']}')");
        }
        
        /**
         * selecionando todos os serviços do pedido que tenham marcado a flag dividir 
         */
        $sqlT147    = <<<EOT
        SELECT * FROM T147 WHERE T147_T005_Id='{$T005_Id_Antigo}' AND T147_Flag_Dividir='S';
EOT;
        $resultT147 = mysql_query($sqlT147);
        while ($linhaT147 = mysql_fetch_array($resultT147)) {
            $upT147       = "UPDATE T147 SET T147_T005_Id='{$novoT005_Id}', T147_Flag_Dividir='N' WHERE T147_Id='{$linhaT147['T147_Id']}'";
            $resultUpT147 = mysql_query($upT147);
            if (!$resultUpT147) {
                mysql_query("ROLLBACK");
                return '3' . mysql_error();
            }
        }
        
        /**
         * selecionando todas as trocas do pedido
         */
        $sqlT138    = "SELECT * FROM T138 WHERE T138_T005_Id='{$T005_Id_Antigo}' AND T138_Flag_Dividir='S';";
        $resultT138 = mysql_query($sqlT138);
        while ($linhaT138 = mysql_fetch_array($resultT138)) {
            
            /**
             * Buscando o D009 correto para a empresa selecionada.
             */
            $sqlD049    = "SELECT D009_D049_Id FROM D009 WHERE D009_Id='{$linhaT138['T138_D009_Id']}'";
            $resultD049 = mysql_query($sqlD049);
            $linhaD049  = mysql_fetch_array($resultD049);
            $erroSQL    = mysql_error();
            if (!empty($erroSQL)) {
                mysql_query("ROLLBACK");
                return '2...' . $erroSQL;
            }
            
            $sqlD009    = "SELECT D009_Id FROM D009 WHERE D009_D049_Id='{$linhaD049['D009_D049_Id']}' AND D009_C004_Id='{$C004_Id_Novo}'";
            $resultD009 = mysql_query($sqlD009);
            $linhaD009  = mysql_fetch_array($resultD009);
            $erroSQL    = mysql_error();
            if (!empty($erroSQL)) {
                mysql_query("ROLLBACK");
                return '3' . $erroSQL;
            }
            if (empty($linhaD009['D009_Id'])) {
                mysql_query("ROLLBACK");
                return '2. D009_Id não encontrado';
            }
            
            $upT138      = "UPDATE T138 SET T138_T005_Id='{$novoT005_Id}', T138_Flag_Dividir='N', T138_C004_Id='{$C004_Id_Novo}', T138_D009_Id='{$linhaD009['D009_Id']}' WHERE T138_Id='{$linhaT138['T138_Id']}'";
            $xresultT138 = mysql_query($upT138);
            if (!$xresultT138) {
                mysql_query("ROLLBACK");
                return '4' . mysql_error();
            }
        }
        mysql_query("call T005_Gravar_Totalizacao_4('{$T005_Id_Novo}')");
        mysql_query("call T005_Gravar_Totalizacao_4('{$T005_Id_Antigo}')");
        
        //Insere registros no histórico do pedido (T178)
        mysql_query("insert into T178 (T178_T005_Id,T178_C007_Id,T178_Data,T178_Descricao,T178_Observacao) values ('{$T005_Id_Antigo}','{$g['usuarioAtual']}',CURRENT_TIMESTAMP(),'Pedido gerou divisão para pedido {$T005_Id_Novo}','')");
        mysql_query("insert into T178 (T178_T005_Id,T178_C007_Id,T178_Data,T178_Descricao,T178_Observacao) values ('{$T005_Id_Novo}','{$g['usuarioAtual']}',CURRENT_TIMESTAMP(),'Pedido gerado da divisão do pedido {$T005_Id_Antigo}','')");
        
        // Verifica se o pedido foi gerado corretamente
        $sqlT005 = mysql_query("SELECT T005_Id FROM T005 WHERE T005_Id='{$T005_Id_Novo}'");
        $mT005  = mysql_fetch_array($sqlT005);

        if (empty($mT005['T005_Id'])) {
