    /**
     * est012MudarFilial
     *
     * @param int $T005_Id_Antigo
     * @param int $C004_Id_Novo
     */
    public function est012MudarFilial($T005_Id_Antigo, $C004_Id_Novo)
    {
        global $g, $novoT005_Id;
        
        require_once('bibliotecas/classes/VEN001.php');
        $VEN001 = new VEN001();
        require_once('bibliotecas/classes/VEN002.php');
        $VEN002 = new VEN002();
        
        mysql_query("SET AUTOCOMMIT=0");
        mysql_query("START TRANSACTION");
        
        $D024  = mysql_query("SELECT T005_D024_Id, T005_C004_Id, T005_C004_Id_Estoque FROM T005 WHERE T005_Id='{$T005_Id_Antigo}'");
        $mD024 = mysql_fetch_array($D024);
        
        //Caso o estoque seja do C004 do orçamento, utilizamos o C004 da empresa a qual o orçamento foi transferido, caso contrario usamos o estoque que estava setado no orçamento
        $T005_C004_Id_Estoque = ($mD024['T005_C004_Id_Estoque'] == $mD024['T005_C004_Id']) ? $C004_Id_Novo : $mD024['T005_C004_Id_Estoque'];

        $D006_Id = $VEN001->retornaCFOP($mD024['T005_D024_Id'], false, $C004_Id_Novo, false, false, false, false, $T005_C004_Id_Estoque);
        
        $sqlUpT005    = "UPDATE T005 SET T005_C004_Id='{$C004_Id_Novo}', T005_D006_Id='{$D006_Id}' WHERE T005_Id='{$T005_Id_Antigo}'";
        $resultUpT005 = mysql_query($sqlUpT005);
        
        $T005  = mysql_query("SELECT * FROM T005 WHERE T005_Id='{$T005_Id_Antigo}'");
        $mT005 = mysql_fetch_array($T005);
        
        if ($mT005['T005_Flag_Status_Financeiro'] == "2") {
            return "Este pedido já foi finalizado";
        }
        
        if (!$resultUpT005) {
            mysql_query("ROLLBACK");
            die($insT005);
            return '1' . mysql_error();
        }
        
        // Nesse método (mudar filial) não é criado um novo pedido, é apenas alterado o C004
        $novoT005_Id = $T005_Id_Antigo;
        
        // Seleciona os itens do pedido para ver se existe algum marcado
        $sqlT006    = "SELECT * FROM T006 WHERE T006_T005_Id='{$T005_Id_Antigo}';";
        $resultT006 = mysql_query($sqlT006);
        
        // Usa a SQL da T006 feita no início do método para fazer update dos teins que foram selecionados para gerar outro pedido 
        while ($linhaT006 = mysql_fetch_array($resultT006)) {
            /**
             * Buscando o D009 correto para a empresa selecionada.
             */
            $sqlD049    = "SELECT D009_D049_Id FROM D009 WHERE D009_Id='{$linhaT006['T006_D009_Id']}'";
            $resultD049 = mysql_query($sqlD049);
            $linhaD049  = mysql_fetch_array($resultD049);
            $erroSQL    = mysql_error();
            if (!empty($erroSQL)) {
                mysql_query("ROLLBACK");
                return '2...' . $erroSQL;
            }
            
            $sqlD009    = "SELECT D009_Id FROM D009 WHERE D009_D049_Id='{$linhaD049['D009_D049_Id']}' AND D009_C004_Id='{$C004_Id_Novo}'";
            $resultD009 = mysql_query($sqlD009);
            $linhaD009  = mysql_fetch_array($resultD009);
            $erroSQL    = mysql_error();
            if (!empty($erroSQL)) {
                mysql_query("ROLLBACK");
                return '3' . $erroSQL;
            }
            if (empty($linhaD009['D009_Id'])) {
                mysql_query("ROLLBACK");
                return 'D009_Id não encontrado';
            }
            
            /**
             * Buscando a CFOP correta para cada item
             */
            $D006_Id = $VEN001->retornaCFOP($mD024['T005_D024_Id'], $linhaD009['D009_Id'], $C004_Id_Novo, false, false, false, false, $T005_C004_Id_Estoque);
            
            /**
             * Faz update nos itens do pedido alterando o T005, C004 (id da empresa nova) e o D009 da nova empresa
             */
            $upT006 = "UPDATE T006 SET T006_C004_Id='{$C004_Id_Novo}', T006_D009_Id='{$linhaD009['D009_Id']}', T006_D006_Id='{$D006_Id}' WHERE T006_Id='{$linhaT006['T006_Id']}'";
            mysql_query($upT006);
            $erroSQL = mysql_error();
            if (!empty($erroSQL)) {
                mysql_query("ROLLBACK");
                return '4' . $erroSQL;
            }
            //mysql_query("call T006_Gravar_Totalizacao_4('{$linhaT006['T006_Id']}')");
        }
        
        /**
         * selecionando todas as trocas do pedido
         */
        $sqlT138    = "SELECT * FROM T138 WHERE T138_T005_Id='{$T005_Id_Antigo}';";
        $resultT138 = mysql_query($sqlT138);
        while ($linhaT138 = mysql_fetch_array($resultT138)) {
            
            /**
             * Buscando o D009 correto para a empresa selecionada.
             */
            $sqlD049    = "SELECT D009_D049_Id FROM D009 WHERE D009_Id='{$linhaT138['T138_D009_Id']}'";
            $resultD049 = mysql_query($sqlD049);
            $linhaD049  = mysql_fetch_array($resultD049);
            $erroSQL    = mysql_error();
            if (!empty($erroSQL)) {
                mysql_query("ROLLBACK");
                return '2...' . $erroSQL;
            }
            
            $sqlD009    = "SELECT D009_Id FROM D009 WHERE D009_D049_Id='{$linhaD049['D009_D049_Id']}' AND D009_C004_Id='{$C004_Id_Novo}'";
            $resultD009 = mysql_query($sqlD009);
            $linhaD009  = mysql_fetch_array($resultD009);
            $erroSQL    = mysql_error();
            if (!empty($erroSQL)) {
                mysql_query("ROLLBACK");
                return '3' . $erroSQL;
            }
            if (empty($linhaD009['D009_Id'])) {
                mysql_query("ROLLBACK");
                return '2. D009_Id não encontrado';
            }
            
            $upT138     = "UPDATE T138 SET T138_C004_Id='{$C004_Id_Novo}', T138_D009_Id='{$linhaD009['D009_Id']}' WHERE T138_Id='{$linhaT138['T138_Id']}'";
            $resultT138 = mysql_query($upT138);
            if (!$resultT138) {
                mysql_query("ROLLBACK");
                return '4' . mysql_error();
            }
        }
        //mysql_query("call T005_Gravar_Totalizacao_4('{$T005_Id_Novo}')");
        $ret = $VEN002->atualizarAliquotasPedidos($novoT005_Id, $C004_Id_Novo);
        if ($ret === true) {
            mysql_query("COMMIT");
            return true;
        } else {
            mysql_query("ROLLBACK");
            return $ret;
        }
    }
    
