        }
        $T005_Id_Novo = $g['mysqlLastId'];
        
        // Selecionando todos os itens do pedido
        $T006 = mysql_query("SELECT * FROM T006 WHERE T006_T005_Id='{$T005_Id_Antigo}'");
        
        while ($mT006 = mysql_fetch_assoc($T006)) {
            $campos  = "";
            $valores = "";
            foreach ($mT006 as $key => $value) {
                if ($key == 'T006_Id') {
