     *
     * @param array $arrayT005
     */
    public function gerarNotaFiscalPedidos($arrayT005){
        
        //A função recebe um array com todos os pedidos a gerar nota
        global $g;
        $sql = '';
        foreach ($arrayT005 as $key => $T005_Id) {
            $sql .= $T005_Id.', ';
        }
        $sql = substr($sql, 0, -2);
        $listaT005 = $sql;
        //Verifica se são todos pedidos de um D024
        $sqlT005 = mysql_query("SELECT DISTINCT T005_D024_Id, T005_D024_Id_Nfe FROM T005 WHERE T005_Id IN({$sql})");
        if(mysql_num_rows($sqlT005) == 1){
            $res = mysql_fetch_array($sqlT005);
            if(!empty($res['T005_D024_Id_Nfe'])){
                $T005_D024_Id_Nfe = $res['T005_D024_Id_Nfe'];
                $T005_D024_Id_Contas = $res['T005_D024_Id_Nfe'];
            } else {
                $T005_D024_Id_Nfe = '';
                $T005_D024_Id_Contas = $res['T005_D024_Id'];
            }                       
            $T005_Id = $arrayT005[0];
        } else {
            //Senão o Id da matriz é selecionado
            $sqlT005 = mysql_query("SELECT T005_D024_Id_Nfe, T005_Id FROM T005 WHERE T005_Id IN({$sql})");
            $res = mysql_fetch_array($sqlT005);
            $T005_D024_Id_Nfe = $res['T005_D024_Id_Nfe'];
            $T005_D024_Id_Contas = $res['T005_D024_Id_Nfe'];
            $T005_Id = $res['T005_Id']; //Caso haja uma matriz, o pedido da Matriz é o selecionado
        }               

        ///////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
        // CONSULTA O PEDIDO
        ///////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
        if($T005_D024_Id_Nfe <= 0){
            $T005_LeftJoin = 'T005_D024_Id';
        }else{
            $T005_LeftJoin = 'T005_D024_Id_Nfe';
        }
        
        $cSql_T005=mysql_query("select * 
                            from T005 
                        left join D006 on D006_Id=T005_D006_Id
