        ///////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
        $sql=mysql_query("select T007_Numero_Nota_Fiscal,T007_Data_Emissao from T007 where T007_T005_Id='{$T005_Id}' and T007_Flag_Cancelada!='S' AND T007_Flag_Inutilizado!='S' AND IFNULL(T007_Protocolo_Inutilizacao,'') = ''");
