         $cSql=mysql_query("update T005 set T005_Flag_Status='4',T005_Flag_Situacao=' ' where T005_Id='{$T005_Id}'");
         
         //Insere registros no histórico do pedido (T178)
         mysql_query("insert into T178(T178_T005_Id,T178_C007_Id,T178_Data,T178_Descricao,T178_Observacao) value ({$T005_Id},{$g['usuarioAtual']},CURRENT_TIMESTAMP(),'Aguardando Coleta Transportadora','')");
         
        }
                        
        //////////////////////////////////////////////////////////////////
        //                                                              //
        //       ATUALIZA CLASSIFICACOES DA NOTA EMITIDA                //
        //                                                              //
        //////////////////////////////////////////////////////////////////
        $Empresa_Grupo='N';
