            $Classificacao=3;
        }
        
        
        // DEVOLUCAO VENDA
        if (($mT005['D006_Flag_Entrada_Saida']=='E') and
            ($mT005['D006_Flag_Venda_Maquina']!='S') and
            ($mT005['D006_Flag_Devolucao']=='S') and
            ($mT005['D006_Flag_Venda_Compra_Outros']=='C') and
