        $mC004 =mysql_fetch_array($C004);
        
        
        //cliente
        $D024 = mysql_query("select * 
                            from D024 
                        left join D020 on D020_Id=D024_D020_Id 
                        left join D018 on D018_Id=D024_D018_Id
                        left join D030 on D030_Id=D024_D030_Id 
