                // include "../pedido_venda/validacao_nfe.php";
            // }
        }
        
        
        
        if (($mD024['D030_Nome_Pais']=='BRASIL') and ($mD024['D018_UF']=='EX'))
        {
            return 'UF do cliente esta definido como EX, Verifique o cadastro do cliente!';
        }
        
        //cotatos
        $D013 = mysql_query("select * from D013 where  D013_D024_Id='{$mD024['D024_Id']}'");
        $mD013 =mysql_fetch_array($D013);
        
        //cfop
        $D006 = mysql_query("select * from D006 where D006_Id='{$mT005['T005_D006_Id']}'");
        $mD006 = mysql_fetch_array($D006);
        
        //transportadora
        $D022 = mysql_query("select * from D022 left join D020 on D020_Id=D022_D020_Id left join D018 on D018_Id=D022_D018_Id where D022_Id='{$mT005['T005_D022_Id']}'");
        $mD022 = mysql_fetch_array($D022);
        
        //tipo de transporte
