        $sql = "select *,
                                D009_Custo_Unitario(D009_Id) Custo_Unitario,
                                (D009_Custo_Unitario(D009_Id)*T006_Quantidade) Custo_Total,
                                D009_Local(D009_Id,1) Local_1,
                                sum(T006_Quantidade) Quantidade
                            from T006
                            left join D037 on D037_Id=T006_D037_Id
                            left join D009 on D009_Id=T006_D009_Id
                            left join D049 on D049_Id=D009_D049_Id
                            left join D001 on D001_Id=D049_D001_Id
                            left join D006 on D006_Id=T006_D006_Id
                                where T006_T005_Id IN({$listaT005})
                                and T006_Quantidade>0
                                and T006_Flag_Status!=3
                                group by T006_D009_Id";

        $sql=mysql_query($sql);

        
        while ($mT006=mysql_fetch_array($sql))
        {
            if($mD006['D006_Flag_Estoque']=='D')
            {
                $Flag_Operacao_Historico="S";
            } 
            elseif($mD006['D006_Flag_Estoque']=='C')
            {
                $Flag_Operacao_Historico="E";
            } 
