    /**
     * gerarNotaFiscalPedidos
     *
     * @param array $arrayT005
     */
    public function xgerarNotaFiscalPedidos($arrayT005)
    {
        //A função recebe um array com todos os pedidos a gerar nota
        global $g;
        $sql = '';
        foreach ($arrayT005 as $key => $T005_Id) {
            $sql .= $T005_Id . ', ';
        }
        $sql       = substr($sql, 0, -2);
        $listaT005 = $sql;
        //Verifica se são todos pedidos de um D024
        $sqlT005   = mysql_query("SELECT DISTINCT T005_D024_Id, T005_D024_Id_Nfe FROM T005 WHERE T005_Id IN({$sql})");
        if (mysql_num_rows($sqlT005) == 1) {
            $res = mysql_fetch_array($sqlT005);
            if (!empty($res['T005_D024_Id_Nfe'])) {
                $T005_D024_Id_Nfe    = $res['T005_D024_Id_Nfe'];
                $T005_D024_Id_Contas = $res['T005_D024_Id_Nfe'];
            } else {
                $T005_D024_Id_Nfe    = '';
                $T005_D024_Id_Contas = $res['T005_D024_Id'];
            }
            $T005_Id = $arrayT005[0];
        } else {
            //Senão o Id da matriz é selecionado
            $sqlT005             = mysql_query("SELECT T005_D024_Id_Nfe, T005_Id FROM T005 WHERE T005_Id IN({$sql})");
            $res                 = mysql_fetch_array($sqlT005);
            $T005_D024_Id_Nfe    = $res['T005_D024_Id_Nfe'];
            $T005_D024_Id_Contas = $res['T005_D024_Id_Nfe'];
            $T005_Id             = $res['T005_Id']; //Caso haja uma matriz, o pedido da Matriz é o selecionado
        }
        
        ///////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
        // CONSULTA O PEDIDO
        ///////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
        if ($T005_D024_Id_Nfe <= 0) {
            $T005_LeftJoin = 'T005_D024_Id';
        } else {
            $T005_LeftJoin = 'T005_D024_Id_Nfe';
        }
        
        $cSql_T005 = mysql_query("select * 
                            from T005 
                        left join D006 on D006_Id=T005_D006_Id
                        left join D059 on D059_Id=D006_D059_Id
                        left join D014 on D014_Id=D006_D014_Id
                        left join D032 on D032_Id=D014_D032_Id
                        left join D024 on D024_Id={$T005_LeftJoin}
                            where T005_Id='{$T005_Id}'");
        $mT005     = mysql_fetch_array($cSql_T005);
        
        $T005_D022_Id = $mT005['T005_D022_Id'];
        $cClausula    = "select * from D022 left join D020 on D020_Id=D022_D020_Id left join D018 on D018_Id=D022_D018_Id where D022_Id='{$T005_D022_Id}'";
        $cSql_D022    = mysql_query($cClausula);
        $mD022        = mysql_fetch_array($cSql_D022);
        
        $mT005['T005_D024_Id'] = $mT005['D024_Id'];
        
        $D048_Id           = 1;
        $mTipoDocumento[1] = "NOTA FISCAL";
        $mTipoDocumento[3] = "ACP";
        $mTipoDocumento[4] = "CUPOM FISCAL";
        $mTipoDocumento[5] = "NOTA FISCAL D1";
        $mTipoDocumento[6] = "NF-e";
        $mTipoDocumento[7] = "NFS-e";
        
        ///////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
        // VERIFICA SE J� EXISTE NF EMITIDA PARA O PEDIDO
        ///////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
        $sql = mysql_query("select T007_Numero_Nota_Fiscal,T007_Data_Emissao from T007 where T007_T005_Id='{$T005_Id}' and T007_Flag_Cancelada!='S' and T007_Flag_Inutilizado!='S'");
        if (mysql_num_rows($sql) > 0) {
            $cMsg_Faturado = "Este pedido já foi faturado:, ";
            while ($mT007 = mysql_fetch_array($sql)) {
                $mT007['T007_Data_Emissao'] = troca_data_dma($mT007['T007_Data_Emissao']);
                $cMsg_Faturado .= "NF: " . $mT007['T007_Numero_Nota_Fiscal'] . " no dia " . $mT007['T007_Data_Emissao'] . ", ";
            }
            return $cMsg_Faturado;
            $cSql = mysql_query("update T005 set T005_Flag_Status='4',T005_Nome_Status = T005_Status_Pedido (T005_Flag_Status, 1),T005_Flag_Situacao=' ' where T005_Id='{$T005_Id}'");
            
