            mysql_query("insert into T178(T178_T005_Id,T178_C007_Id,T178_Data,T178_Descricao,T178_Observacao) value ({$T005_Id},{$g['usuarioAtual']},CURRENT_TIMESTAMP(),'Enviou para coleta','')");
            
        }
                
