        if (($mT005['D006_Flag_Entrada_Saida'] == 'S') and ($mT005['D006_Flag_Venda_Maquina'] != 'S') and ($mT005['D006_Flag_Gera_Contas'] == 'R') and ($mT005['D006_Flag_Devolucao'] != 'S') and ($mT005['D006_Flag_Venda_Compra_Outros'] == 'V') and (($mT005['D024_Flag_Mono'] == '1') or ($Empresa_Grupo == 'S'))) {
            $Classificacao = 5;
        }
        
        // IMPORTACAO
        if (($mT005['D006_Flag_Entrada_Saida'] == 'E') and ($mT005['D006_Flag_Devolucao'] != 'S') and ($mT005['D006_Flag_Venda_Compra_Outros'] == 'O') and ($mT005['D006_Flag_Estado'] == 'I') and ($mT005['D024_Flag_Mono'] != '1') and ($Empresa_Grupo == 'N')) {
            $Classificacao = 3;
        }
        
        // DEVOLUCAO VENDA
        if (($mT005['D006_Flag_Entrada_Saida'] == 'E') and ($mT005['D006_Flag_Venda_Maquina'] != 'S') and ($mT005['D006_Flag_Devolucao'] == 'S') and ($mT005['D006_Flag_Venda_Compra_Outros'] == 'C') and ($mT005['D024_Flag_Mono'] != '1') and ($Empresa_Grupo == 'N')) {
            $Classificacao = 2;
        }
        
        /////////////////////////////////////////////////////////////////////////////////////////
        // VALIDACOES
        /////////////////////////////////////////////////////////////////////////////////////////
        if ($mT005['T005_D006_Id'] == 0) {
            return 'Falta preencher o campo natureza da operação';
        }
        
