            return 'Vendedor Interno não foi gravado no pedido. Verifique!';
        }
        
        if ($g['empresaAtual'] != $mT005['T005_C004_Id']) {
            return "A Empresa selecionada não é a mesma do pedido., Empresa Selecionada:" . $g['empresaAtual'];
        }
        
        //empresa usuaria
        $C004  = mysql_query("select * from C004 left join D020 on D020_Id=C004_D020_Id left join D018 on D018_Id=C004_D018_Id where C004_Id = '{$mT005['T005_C004_Id']}'");
        $mC004 = mysql_fetch_array($C004);
        
        
