    /**
     * validacaoNFE3
     *
     * @param array $mD024
     * @param array $mC004
     * @param array $mT005
     * @param array $mD022
     * @param array $mT006
     * @param array $mC004
     * @param int $T005_Id
     */
    public function validacaoNFE3($mD024, $mC004, $mT005, $mD022, $mT006, $T005_Id)
    {
        $mRestricoesCliente = array();
        
        if ($mD024['D024_Flag_Pre_Cadastro'] == 'S') {
            $mRestricoesCliente[] = ". Este Cliente É <b>PRÉ-CADASTRO</b><br />";
        }
        
        //-- ELIMINA PONTOS E TRACOS DO TELEFONE
        $mD024['D024_Telefone_1'] = str_replace(array(
            ".",
            "-",
            "/",
            " "
        ), "", $mD024['D024_Telefone_1']);
        
        ///////////////////////////////////////////////////////////////////////
        //-- VALIDACOES DO REMENTENTE
        ///////////////////////////////////////////////////////////////////////
        
        if (strlen($mC004['C004_CNAE_Fiscal']) < 7 && !empty($mC004['C004_Inscricao_Municipal'])) {
            $mRestricoesNFe[] = "CNAE <b>{$mC004['C004_CNAE_Fiscal']}</b> do emitente é inferior a 7 caracteres<br />";
        }
        
        if ($mT005['T005_Data_Saida'] != '0000-00-00') {
            if (intval(str_replace("-", "", $mT005['T005_Data_Saida'])) < intval(str_replace("-", "", troca_data_amd(hoje())))) {
                $mRestricoesNFe[] = "<b>Data de Saída: " . troca_data_dma($mT005['T005_Data_Saida']) . "</b> é menor que a data atual: " . hoje() . "<br />";
            }
        }
        
        ///////////////////////////////////////////////////////////////////////
        //-- VALIDACOES DO TRANSPORTADOR
        ///////////////////////////////////////////////////////////////////////
        if (!empty($mD022['D022_Cnpj']) or !empty($mD022['D022_Cpf'])) {
            //-- FAZ A VALIDACAO DOS DEMAIS CAMPOS APENAS SE EXISTIR CNPJ OU CPF
            
            if (!empty($mD022['D022_Cnpj'])) {
                $cCnpjTransportador = $mD022['D022_Cnpj'];
                $cCnpjTransportador = str_replace(".", "", $cCnpjTransportador);
                $cCnpjTransportador = str_replace("-", "", $cCnpjTransportador);
                $cCnpjTransportador = str_replace(" ", "", $cCnpjTransportador);
                $cCnpjTransportador = str_replace("/", "", $cCnpjTransportador);
                if (strlen($cCnpjTransportador) != 14) {
                    $mRestricoesNFe[] = "<b>Cnpj do transportador</b> foi informado de forma incorreta: " . $mD022['D022_Cnpj'] . "<br />";
                }
                $mD022['D022_Cnpj'] = $cCnpjTransportador;
            } elseif (!empty($mD022['D022_Cpf'])) {
                $cCpfTransportador = $mD022['D022_Cpf'];
                $cCpfTransportador = str_replace(".", "", $cCpfTransportador);
                $cCpfTransportador = str_replace("-", "", $cCpfTransportador);
                $cCpfTransportador = str_replace(" ", "", $cCpfTransportador);
                $cCpfTransportador = str_replace("/", "", $cCpfTransportador);
                if (strlen($cCpfTransportador) != 11) {
                    $mRestricoesNFe[] = "Cpf do transportador</b> foi informado de forma incorreta: " . $mD022['D022_Cpf'] . "<br />";
                }
                $mD022['D022_Cnpj'] = $cCpfTransportador;
            }

            if(empty($mT005['T005_Quantidade_Volumes']) && $mT005['T005_Flag_ACP'] == '6'){
                $mRestricoesNFe[] = "Quantidade de volumes não informada. Verifique na aba \"Frete\"<br />";
            }
            
            if (empty($mD022['D020_Nome_Cidade'])) {
                $mRestricoesNFe[] = "Cidade do transportador não foi informado no cadastro.<br />";
            }
            if (empty($mD022['D018_UF'])) {
                $mRestricoesNFe[] = "Estado do transportador não foi informado no cadastro.>br />";
            }
            if (empty($mD022['D022_Endereco'])) {
                $mRestricoesNFe[] = "Endereço do transportador não foi informado no cadastro.<br />";
            }
            if (!empty($mT005['T005_Transportadora_Placa_Veiculo'])) {
                if (strlen($mT005['T005_Transportadora_Placa_Veiculo']) != 7) {
                    $mRestricoesNFe[] = "Placa do Veiculo esta incorreta. Caso tenha preenchido, não coloque hífen (-) ou espaço<br />";
                }
                if (empty($mT005['T005_Estado_Veiculo'])) {
                    $mRestricoesNFe[] = "Informe a UF do veículo<br />";
                }
            }
        } else {
            if (!empty($mT005['T005_Transportadora_Placa_Veiculo'])) {
                $mRestricoesNFe[] = "Foi informado a placa do veículo, porém, não foi informado a transportadoraSe foi apenas preenchido o nome do transportador, então não deve ser preenchido a placa do veículo, caso contrario, cadastre a transportadora<br />";
            }
            
        }
        
        ///////////////////////////////////////////////////////////////////////
        //-- VALIDACOES DO DESTINATARIO
        ///////////////////////////////////////////////////////////////////////
        if ($mD024['D024_Flag_Pessoa_Fisica_Juridica'] == 'F') {
            if (strlen($mD024['D024_Cpf']) <= 0) {
                $mRestricoesCliente[] = ". CPF não foi preenchido no cadastro do cliente<br />";
            } elseif (strlen($mD024['D024_Cpf']) != 14) {
                $mRestricoesCliente[] = ". CPF foi preenchido incorretamente no cadastro do cliente<br />";
            } elseif (!validar_cpf($mD024['D024_Cpf'])) {
                $mRestricoesCliente[] = ". CPF inválido: " . $mD024['D024_Cpf'];
            }
        } elseif ($mD024['D024_Flag_Pessoa_Fisica_Juridica'] == 'J') {
            if (strlen($mD024['D024_Cnpj']) <= 0) {
                $mRestricoesCliente[] = ". CNPJ não foi preenchido no cadastro do cliente<br />";
            } elseif (strlen($mD024['D024_Cnpj']) != 18) {
                $mRestricoesCliente[] = ". CNPJ foi preenchido incorretamente no cadastro do cliente<br />";
            } elseif (!validar_cnpj($mD024['D024_Cnpj'])) {
                $mRestricoesCliente[] = ". CNPJ inválido: " . $mD024['D024_Cnpj'];
            }
        }
        if (strlen($mD024['D024_Nome_Empresa']) <= 0) {
            $mRestricoesCliente[] = "Nome do Cliente não foi preenchido no cadastro do cliente<br />";
        }
        if (strlen($mD024['D024_Endereco']) <= 2) {
            $mRestricoesCliente[] = ". Endereço possui menos de 3 caracteres no cadastro do cliente<br />";
        }
        if (strlen($mD024['D024_Endereco']) > 60) {
            $mRestricoesCliente[] = ". Endereço possui mais de 3 caracteres no cadastro do cliente<br />";
        }
        if (strlen($mD024['D024_Numero']) == 0) {
            $mRestricoesCliente[] = "Numero não foi preenchido no cadastro do cliente.<br />";
        }
        if (strlen($mD024['D024_Numero']) > 60) {
            $mRestricoesCliente[] = "Numero possui mais de 60 caracteres no cadastro do cliente.<br />";
        }
        if (strlen($mD024['D024_Complemento']) > 60 && !empty($mD024['D024_Complemento'])) {
            $mRestricoesCliente[] = ". Complemento possui mais de 60 caracteres no cadastro do cliente.<br />";
        }
        if (strlen($mD024['D024_Bairro']) <= 2) {
            $mRestricoesCliente[] = ". Bairro " . $mD024['D024_Bairro'] . " possui menos de 3 caracteres no cadastro do cliente.<br />";
        }
        if (strlen($mD024['D024_Bairro']) > 60) {
            $mRestricoesCliente[] = ". Bairro " . $mD024['D024_Bairro'] . " possui mais de 60 caracteres no cadastro do cliente.<br />";
        }
        if (empty($mD024['D020_Codigo_IBGE'])) {
            $mRestricoesCliente[] = ". Cidade " . $mD024['D020_Nome_Cidade'] . " não possui código de identificação do IBGE<br />";
        }
        if (strlen($mD024['D020_Nome_Cidade']) <= 2) {
            $mRestricoesCliente[] = ". Cidade " . $mD024['D020_Nome_Cidade'] . " possui menos de 3 caracteres.<br />";
        }
        if (strlen($mD024['D020_Nome_Cidade']) > 60) {
            $mRestricoesCliente[] = ". Cidade possui mais de 3 caracteres no cadastro de cidades: " . $mD024['D020_Id'] . " - " . $mD024['D020_Nome_Cidade'] . "<br />";
        }
        if (empty($mD024['D018_Codigo_IBGE'])) {
            $mRestricoesCliente[] = ". Estado: " . $mD024['D018_Estado'] . "não possui c�digo de identificação do IBGE<br />";
        }
        if (strlen($mD024['D018_UF']) != 2) {
            $mRestricoesCliente[] = ". Estado preenchido incorretamente no cadastro de Estados: " . $mD024['D018_Id'] . " - " . $mD024['D018_UF'] . "<br />";
        }
        $cCepDestinatario = str_replace(".", "", $mD024['D024_Cep']);
        $cCepDestinatario = str_replace("-", "", $cCepDestinatario);
        $cCepDestinatario = str_replace(" ", "", $cCepDestinatario);
        $cCepDestinatario = trim($cCepDestinatario);
        if (strlen($cCepDestinatario) == 0) {
            $mRestricoesCliente[] = ". Cep não foi informado.";
        }
        if (strlen($cCepDestinatario) != 8) {
            $mRestricoesCliente[] = ". Cep foi preenchido incorretamente. O campo deve contar 8 caracteres numerico no cadastro do cliente.<br />";
        }
        
        $mD024['D024_DDD_Telefone_1'] = str_replace("(", "", $mD024['D024_DDD_Telefone_1']);
        $mD024['D024_DDD_Telefone_1'] = str_replace(")", "", $mD024['D024_DDD_Telefone_1']);
        $mD024['D024_DDD_Telefone_1'] = str_replace(" ", "", $mD024['D024_DDD_Telefone_1']);
        $mD024['D024_DDD_Telefone_1'] = trim($mD024['D024_DDD_Telefone_1']);
        
        $mD024['D024_Telefone_1'] = str_replace("(", "", $mD024['D024_Telefone_1']);
        $mD024['D024_Telefone_1'] = str_replace(")", "", $mD024['D024_Telefone_1']);
        $mD024['D024_Telefone_1'] = str_replace("-", "", $mD024['D024_Telefone_1']);
        $mD024['D024_Telefone_1'] = str_replace(".", "", $mD024['D024_Telefone_1']);
        $mD024['D024_Telefone_1'] = str_replace(" ", "", $mD024['D024_Telefone_1']);
        $mD024['D024_Telefone_1'] = trim($mD024['D024_Telefone_1']);
        
        if (!empty($mD024['D024_DDD_Telefone_1']) && !empty($mD024['D024_Telefone_1']) && strlen($mD024['D024_DDD_Telefone_1']) != 2) {
            //$mRestricoesCliente[] = ". Campo DDD telefone tem menos de 2 caracteres no cadastro do cliente.";
        }
        if (!empty($mD024['D024_DDD_Telefone_1']) && !empty($mD024['D024_Telefone_1']) && (strlen($mD024['D024_Telefone_1']) != 8 && strlen($mD024['D024_Telefone_1']) != 9)) {
            //$mRestricoesCliente[] = ". Campo telefone deve ser preenchido com até 9 carateres numericos no cadastro do cliente.<br />";
        }
        
        $mD024['D024_Inscricao_Estadual'] = str_replace(".", "", $mD024['D024_Inscricao_Estadual']);
        $mD024['D024_Inscricao_Estadual'] = str_replace("-", "", $mD024['D024_Inscricao_Estadual']);
        $mD024['D024_Inscricao_Estadual'] = str_replace(" ", "", $mD024['D024_Inscricao_Estadual']);
        $mD024['D024_Inscricao_Estadual'] = str_replace("/", "", $mD024['D024_Inscricao_Estadual']);
        $mD024['D024_Inscricao_Estadual'] = trim($mD024['D024_Inscricao_Estadual']);
        if (!empty($mD024['D024_Inscricao_Estadual']) && strlen($mD024['D024_Inscricao_Estadual']) < 3) {
            $mRestricoesCliente[] = ". Inscrição Estadual tem menos de 2 caracteres no cadastro do cliente.<br />";
            
        }
        if (!empty($mD024['D024_Inscricao_Estadual']) && strlen($mD024['D024_Inscricao_Estadual']) > 14) {
            $mRestricoesCliente[] = ". Inscrição Estadual tem mais de 14 caracteres no cadastro do cliente.<br />";
            
        }
        
        $mD024['D024_Numero_Suframa'] = str_replace(".", "", $mD024['D024_Numero_Suframa']);
        $mD024['D024_Numero_Suframa'] = str_replace("-", "", $mD024['D024_Numero_Suframa']);
        $mD024['D024_Numero_Suframa'] = str_replace(" ", "", $mD024['D024_Numero_Suframa']);
        $mD024['D024_Numero_Suframa'] = str_replace("/", "", $mD024['D024_Numero_Suframa']);
        $mD024['D024_Numero_Suframa'] = trim($mD024['D024_Numero_Suframa']);
        if (!empty($mD024['D024_Numero_Suframa']) && strlen($mD024['D024_Numero_Suframa']) != 9) {
            $mRestricoesCliente[] = "Suframa deve ter 9 caracteres no cadastro do cliente.<br />";
            
        }
        if (count($mRestricoesCliente) > 0) {
            $mRestricoesNFe[] = "Cliente: " . $mD024['D024_Id'] . "-" . $mD024['D024_Nome_Empresa'];
            for ($x = 0; $x < count($mRestricoesCliente); $x++) {
                $mRestricoesNFe[] = $mRestricoesCliente[$x];
            }
            //     $mRestricoesNFe[]="<hr>";
        }
        
        ///////////////////////////////////////////////////////////////////////
        //-- VALIDACAO DOS ITENS
        ///////////////////////////////////////////////////////////////////////
        $cClausula = " select ";
        $cClausula .= " * ";
        $cClausula .= " from T006 ";
        $cClausula .= " left join D006 on D006_Id=T006_D006_Id ";
        $cClausula .= " left join D059 on D059_Id=T006_D059_Id ";
        $cClausula .= " where T006_T005_Id='{$T005_Id}' ";
        $cClausula .= " order by T006_Item, T006_Id desc";
        $cSql_T006 = mysql_query($cClausula);
        $cErro     = mysql_error();
        if (!empty($cErro)) {
            return "Ocorreu um erro";
            //$mRestricoesNFe[] = "Ocorreu um erro: ";
        }
        
        while ($mT006 = mysql_fetch_array($cSql_T006)) {
            unset($mRestricoesItem);
            
            $mT006['T006_Codigo_Produto'] = str_replace(trim("\ "), "", $mT006['T006_Codigo_Produto']);
            $mT006['T006_Codigo_Produto'] = str_replace("'", "", $mT006['T006_Codigo_Produto']);
            $mT006['T006_Codigo_Produto'] = str_replace('"', "", $mT006['T006_Codigo_Produto']);
            $cSituacao_Tributaria         = substr($mT006['T006_Flag_Situacao_Tributaria'], -2);
            if (empty($mT006['D006_Codigo_CFOP'])) {
                $mRestricoesItem[] = "Não foi selecionada a CFOP<br />";
            }
            if (empty($mT006['T006_Descricao_Produto'])) {
                $mRestricoesItem[] = "Não foi informado uma descrição para o item<br />";
            }
            if (empty($mT006['T006_Situacao_Tributaria_IPI'])) {
                $mRestricoesItem[] = "Não foi informado Situação Tributária do IPI<br />";
            }
            
            if (!empty($mT006['D006_Codigo_CFOP']) && !validarCFOP($mT006['D006_Codigo_CFOP'])) {
                $mRestricoesItem[] = ". CFOP inválida: " . $mT006['D006_Codigo_CFOP'];
            }
            $cClassificacao_Fiscal = str_replace(".", "", $mT006['T006_Classificacao_Fiscal']);
            if (!empty($cClassificacao_Fiscal) && strlen($cClassificacao_Fiscal) != 8) {
                $mRestricoesItem[] = ". Classificação fiscal deve ter 8 caracteres: " . $cClassificacao_Fiscal . "<br />";
            }
            if (empty($cSituacao_Tributaria)) {
                $mRestricoesItem[] = "Não foi definida a situação tributaria<br />";
            }
            if ($mT006['T006_Situacao_Tributaria_PIS'] != '01' && $mT006['T006_Situacao_Tributaria_PIS'] != '02' && $mT006['T006_Situacao_Tributaria_PIS'] != '03' && $mT006['T006_Situacao_Tributaria_PIS'] != '04' && $mT006['T006_Situacao_Tributaria_PIS'] != '06' && $mT006['T006_Situacao_Tributaria_PIS'] != '07' && $mT006['T006_Situacao_Tributaria_PIS'] != '08' && $mT006['T006_Situacao_Tributaria_PIS'] != '09' && $mT006['T006_Situacao_Tributaria_PIS'] != '99') {
                $mRestricoesItem[] = "Situação tributaria do PIS: " . $mT006['T006_Situacao_Tributaria_PIS'] . " é inválida<br />";
            }
            if ($mT006['T006_Situacao_Tributaria_COFINS'] != '01' && $mT006['T006_Situacao_Tributaria_COFINS'] != '02' && $mT006['T006_Situacao_Tributaria_COFINS'] != '03' && $mT006['T006_Situacao_Tributaria_COFINS'] != '04' && $mT006['T006_Situacao_Tributaria_COFINS'] != '06' && $mT006['T006_Situacao_Tributaria_COFINS'] != '07' && $mT006['T006_Situacao_Tributaria_COFINS'] != '08' && $mT006['T006_Situacao_Tributaria_COFINS'] != '09' && $mT006['T006_Situacao_Tributaria_COFINS'] != '99') {
                $mRestricoesItem[] = "Situalção tributaria do COFINS: " . $mT006['T006_Situacao_Tributaria_PIS'] . " é inválida<br />";
            }
        }
        
        if (count($mRestricoesNFe) > 0) {
            $Msg = implode(',,', $mRestricoesNFe);
            return $Msg;
        } else {
            return true;
        }
    }
    
    /**
     * gerarNotaFiscalCupom - Transforma um CUPOM FISCAL em NF-e
     *
     * @param int $T007_Id
     */
    public function gerarNotaFiscalCupom($T007_Id)
    {
        global $g;
        mysql_query("START TRANSACTION");

        if(!empty($g['C031']['exibirNoDanfeValorTribTransp']) && $g['C031']['exibirNoDanfeValorTribTransp'] == 'S'){
            $T007_Flag_Trib_Transparencia = 'S';
        } else {
            $T007_Flag_Trib_Transparencia = 'N';
        }
        
        // Converte em NF-e
        $fusoHorario = date('P');
        $sql = "UPDATE T007 SET T007_Flag_ACP = '6', T007_Flag_Expedicao = 2, T007_Empresa_Usuaria_CRT = '{$g['C004']['C004_Codigo_Regime_Tributario']}', T007_Versao_NFe = '{$g['c004']['C004_Versao_NFe']}', T007_Flag_Almoxarifado = 'S', T007_Flag_Destino_Produto = 3, T007_Flag_Trib_Transparencia = '{$T007_Flag_Trib_Transparencia}', T007_Fuso_Horario_Saida = '{$fusoHorario}', T007_Fuso_Horario_Emissao = '{$fusoHorario}', T007_Hora_Emissao = current_time(), T007_Hora_Saida = current_time(), T007_Versao_NFe = '{$g['C020']['C020_Versao_NFe']}' WHERE T007_Id = '{$T007_Id}'";
        mysql_query($sql);
        if (mysql_error()) {
            mysql_query("ROLLBACK");
            return $sql . ' - ' . mysql_error();
        }
        $sql = "UPDATE T008 SET T008_Flag_Destino_Produto = 3 WHERE T008_T007_Id = '{$T007_Id}'";
        mysql_query($sql);
