            $cClausula = "call T008_Gravar_Totalizacao_4({$mT008_Novo['T008_Id']})";
            mysql_query($cClausula);
            if (mysql_error()) {
                mysql_query("ROLLBACK");
                return mysql_error();
            }
        }
        
        // Selects
        $sql  = "SELECT * FROM T007 WHERE T007_Id = '{$T007_Id}'";
