        }
        $mT007     = mysql_fetch_assoc($T007);
        $C004      = mysql_query("select * from C004 left join D020 on D020_Id=C004_D020_Id left join D018 on D018_Id=C004_D018_Id where C004_Id = '{$mT007['T007_C004_Id']}'");
        $mC004     = mysql_fetch_array($C004);
