     /**
     * separarPedido
     *
     * @param int T005_Id
     * @return bool
     */
    public function separarPedido($T005_Id){    
        
        global $g;

        $sql = <<<EOT
        SELECT T006_Id,
               T006_T005_Id,
               T006_T066_Id,
               T006_Quantidade_Separacao,
               T006_Quantidade,
               T006_Codigo_Produto,
               T006_Descricao_Produto,
               D006_Flag_Estoque,
               GROUP_CONCAT(DISTINCT T066_Id SEPARATOR '|') AS T066_Id_Mais
          FROM T006
     LEFT JOIN T066 ON T066_D009_Id=T006_D009_Id
     LEFT JOIN D006 ON T006_D006_Id=D006_Id
     LEFT JOIN T005 ON T006_T005_Id=T005_Id
     LEFT JOIN T238 ON T238_T006_Id=T006_Id
         WHERE T006_T005_Id='{$T005_Id}'
           AND (IFNULL(T006_Quantidade_Separacao, 0) < T006_Quantidade OR IFNULL(T238_T006_Id, 0) <= 0)
           AND IF(IFNULL(T006_C004_Id_Estoque,0) > 0, T006_C004_Id_Estoque, T005_C004_Id) = T005_C004_Id
      GROUP BY T006_Id
EOT;
        $resT006 = mysql_query($sql);
        if (mysql_num_rows($resT006) > 0) {

            //Preencher a separação
            $produtosSemLocal  = 0;
            $locacaoSemEstoque = 0;
            $codigosSemLocacao = '';
            $codigoSemEstoque  = '';
            while ($rowT006 = mysql_fetch_assoc($resT006)) {
                $T066_Id = $rowT006['T006_T066_Id'];
                if ($T066_Id) {
                    $D004_Id                              = getD004($T066_Id);
                    $rowT006['T006_Quantidade_Separacao'] = empty($rowT006['T006_Quantidade_Separacao']) ? 0 : $rowT006['T006_Quantidade_Separacao'];
                    $rowT006['T006_Quantidade']           = empty($rowT006['T006_Quantidade']) ? 0 : $rowT006['T006_Quantidade'];
                    
                    if($g['C031']['permitirFaturarSemEstoque'] == 'S'){

                        $sqlQtdeSeparacao = mysql_query("SELECT SUM(T238_Quantidade_Separacao) as Quantidade_Separacao
                                                           FROM T238 
                                                          WHERE T238_T006_Id = '{$rowT006['T006_Id']}'");

                        $rowQtdeSeparacao                     = mysql_fetch_array($sqlQtdeSeparacao);
                        $rowT006['T006_Quantidade_Separacao'] = $rowQtdeSeparacao['Quantidade_Separacao'];

                    } else {

                        $sqlT066 = mysql_query("SELECT T066_Quantidade_Estoque 
                                                  FROM T066 
                                                 WHERE T066_Id = '{$T066_Id}'");

                        $rowT066 = mysql_fetch_array($sqlT066);
                    }

                    $qtd = $rowT006['T006_Quantidade'] - $rowT006['T006_Quantidade_Separacao'];
                    
                    //Verifica se a primeira locação possui estoque suficiente
                    if($rowT066['T066_Quantidade_Estoque'] < $qtd && $g['C031']['permitirFaturarSemEstoque'] == 'N' && $rowT006['D006_Flag_Estoque'] != 'N'){
                        
                        $locacaoSemEstoque++;
                        $rowT066['T066_Quantidade_Estoque'] = gCorrigeNumero($rowT066['T066_Quantidade_Estoque']);
                        $qtd = gCorrigeNumero($qtd);
                        $codigosSemEstoque .= "{$rowT006['T006_Codigo_Produto']} - {$rowT006['T006_Descricao_Produto']} - {$rowT066['T066_Quantidade_Estoque']}/{$qtd}<br>";
                   
                    } else {

                        if (!empty($D004_Id) || (empty($D004_Id) && $rowT006['D006_Flag_Estoque'] == 'N')) {

                            $sql = "INSERT INTO T238 (T238_T005_Id, 
                                                      T238_T006_Id, 
                                                      T238_T066_Id, 
                                                      T238_D004_Id, 
                                                      T238_Quantidade_Separacao
                                            ) VALUES (
                                                     '{$rowT006['T006_T005_Id']}',
                                                     '{$rowT006['T006_Id']}',
                                                     '{$T066_Id}',
                                                     '{$D004_Id}',
                                                     '{$qtd}')";

                            mysql_query($sql);
                            $erro = mysql_error();
                            if(!empty($erro)){
                                return "Erro  ao inserir dados na separação: " . $erro;
                            }

                        } else {
                            $produtosSemLocal++;
                            $codigosSemLocacao .= 'Código '.$rowT006['T006_Codigo_Produto']."<br>";
                        }
                    }
                }
            }

            if($produtosSemLocal > 0){
                if($produtosSemLocal == 1){
                    mysql_query("ROLLBACK");
                    //VP42
                    return $produtosSemLocal . " produto não pode ser preenchido pois não possui locação.<br><br>".$codigosSemLocacao;
                } else {
                    mysql_query("ROLLBACK");
                    return $produtosSemLocal . " produtos não puderam ser preenchidos por não possuirem locação.<br><br>".$codigosSemLocacao;
                }
            }
            if($locacaoSemEstoque > 0){
                if($locacaoSemEstoque == 1){
                    mysql_query("ROLLBACK");
                    //VP43
                    return $locacaoSemEstoque . " produto não possui estoque suficiente na primeira locação<br><br>".$codigosSemEstoque;
                } else {
                    mysql_query("ROLLBACK");
                    return $locacaoSemEstoque . " produtos não pussuem estoque suficiente na primeira locação.<br><br>".$codigosSemEstoque;
                }
            }
        }

        return true;
    }

