    /**
     * retornaProximaNF
     *
     * @param int T005_Flag_ACP
     * @param int C004_Id
     * @return array 
     */
    public function retornaProximaNF($flagACP, $C004_Id){
        global $g;

        $tipo = array(1 => 'NF', 3 => 'ACP', 4 => 'CP', 6 => 'NFe', 8 => 'NFCe');

        $C004 = mysql_query("select C004_Ultimo_Numero_Nota_Fiscal,
                                    C004_Ultimo_Numero_ACP,
                                    C004_Ultimo_Numero_Cupom_Fiscal,
                                    C004_Ultimo_Numero_Nota_Fiscal_Eletronica,
                                    C004_Ultimo_Numero_NFCe,
                                    C004_Ultimo_Numero_Serie_NFE,
                                    C004_Ultimo_Numero_Serie_NFCE                           
                               from C004 
                              where C004_Id= '{$C004_Id}' ");
        $mC004 = mysql_fetch_array($C004);

        if ($flagACP == 1){ // nota fiscal
            $ultimoNumero = $mC004['C004_Ultimo_Numero_Nota_Fiscal'];

        } else if ($flagACP == 2){ // Romaneio
            $ultimoNumero = '';

        } else if ($flagACP == 3){ //ACP
            $ultimoNumero = $mC004['C004_Ultimo_Numero_ACP'];

        } else if ($flagACP == 4){ // cupom fiscal
            $ultimoNumero = $mC004['C004_Ultimo_Numero_Cupom_Fiscal'];

        } else if ($flagACP == 5){ // NF D1
            //$ultimoNumero = '';
            // numero da nota é digitado a mao
            return true;

        } else if ($flagACP == 6){ // NFe
            $ultimoNumero = $mC004['C004_Ultimo_Numero_Nota_Fiscal_Eletronica'];
            $ultimaSerie  = $mC004['C004_Ultimo_Numero_Serie_NFE'];

        } else if ($flagACP == 7){ // NFSe
            //$ultimoNumero = '';
            // numero da nota é digitado a mao
            return true;

        } else if ($flagACP == 8){ // NFCe
            $ultimoNumero = $mC004['C004_Ultimo_Numero_NFCe'];
            $ultimaSerie  = $mC004['C004_Ultimo_Numero_Serie_NFCE'];
        }

        if ($g['C020']['C020_NFe_SCAN_Ativado'] == 'S') {
            $ultimaSerie = 900;
        }

        if($ultimaSerie == 0 || empty($ultimaSerie)){
            $ultimaSerie = 1;
        }

        $proximoNumero = str_replace('A','',$ultimoNumero) + 1;

        if($flagACP == 3){
            $proximoNumero = 'A'.$proximoNumero;
        }

        //verifica se existe o ultimo número
        $ultimo = mysql_query("select T007_Id 
                                 from T007
                                where T007_C004_Id= '{$C004_Id}'
                                  and T007_Flag_ACP = '{$flagACP}'
                                  and T007_Serie = '{$ultimaSerie}' 
                                  and T007_Numero_Nota_Fiscal = '{$ultimoNumero}'");

        if(mysql_num_rows($ultimo) <= 0 && $ultimoNumero > 0 ){
            return array(false, "Falta {$tipo[$flagACP]} com Nº {$ultimoNumero}. Verifique a última {$tipo[$flagACP]} emitida se confere com o <b>\"Último Nº {$tipo[$flagACP]}\"</b> no cadastro da empresa");
        }

        //verifica se existe o próximo número
        $proximo = mysql_query("select T007_Id 
                                  from T007
                                 where T007_C004_Id = '{$C004_Id}'
                                   and T007_Flag_ACP = '{$flagACP}'
                                   and T007_Serie = '{$ultimaSerie}' 
                                   and T007_Numero_Nota_Fiscal = '{$proximoNumero}'");

        if(mysql_num_rows($proximo) > 0 ){
            return array(false, "Já existe {$tipo[$flagACP]} com Nº {$proximoNumero}. Verifique a última {$tipo[$flagACP]} emitida se confere com o <b>\"Último Nº {$tipo[$flagACP]}\"</b> no cadastro da empresa");
        }
        
        // Verifica se tem notas emitidas quando o próximo número é 1 ou A1
        if($proximoNumero == 1 || $proximoNumero == "A1"){
            
            $T007 = mysql_query("select T007_Id, 
                                        T007_Numero_Nota_Fiscal
                                   from T007
                                  where T007_C004_Id = '{$C004_Id}'
                                    and T007_Flag_ACP = '{$flagACP}'
                                    and T007_Serie = '{$ultimaSerie}'
                                    and (T007_Numero_Nota_Fiscal > 1 OR T007_Numero_Nota_Fiscal > 'A1')
                               order by T007_Id desc limit 1");
                                
            $mT007 = mysql_fetch_array($T007);

            if(mysql_num_rows($T007) > 0 ){
                return array(false, "Última {$tipo[$flagACP]} emitida possui Nº {$mT007['T007_Numero_Nota_Fiscal']}. Verifique se confere com o <b>\"Último Nº {$tipo[$flagACP]}\"</b> no cadastro da empresa");
            }            
        }
        
        return array($proximoNumero, $ultimaSerie);
    }

     /**
     * retornaIndicadorPresenca
     *
     * @param int T005_Flag_ACP
     * @param varchar T005_Canal_Vendas_Ecommerce
     */
    public function retornaIndicadorPresenca($flagACP, $canalVendas){
        global $g;

        if($flagACP == 8){
            // Operação presencial   
            $indicadorPresenca = 1;     
        } else if(!empty($canalVendas)){
            // Operação não presencial, pela Internet
            $indicadorPresenca = 2; 
        } else {
            // Operação não presencial, Teleatendimento
            $indicadorPresenca = 3; 
        }        

        return $indicadorPresenca;
    }

    /**
     * retornaIntermediadorTransacao
     *
     * @param int indicadorPresenca
     * @param varchar D027_Cnpj_Intermediador_Transacao
     */
    public function retornaIntermediadorTransacao($indicadorPresenca, $cnpjIntermediador){
        global $g;

        if($indicadorPresenca == 1){  
            $intermediador = '';     
        } else if(!empty($cnpjIntermediador)){
            // Operação com intermediador
            $intermediador = 1; 
        } else {
            // Operação sem intermediador
            $intermediador = 0; 
        }        
        
        return $intermediador;
    }
 

       /**
     * Envia NF-e em Lote
     */
    public function enviarLoteNfe($numLote) {
        global $g;        

        if(empty($numLote))
           return array(false,"Não foi informado o número do Lote");

        $T007 = mysql_query("SELECT T007_Empresa_Usuaria_Cnpj,
                                    T007_Empresa_Usuaria_Uf,
                                    T007_Empresa_Usuaria_Codigo_Estado_IBGE,
                                    T007_Ambiente_NFe,
                                    C004_Localizacao_Certificados,
                                    C020_NFe_Tipo_Certificado,                             
                                    C004_Senha_Certificados,
                                    C004_Id
                                FROM T007 
                                LEFT JOIN C004 ON C004_Id = T007_C004_Id
                                LEFT JOIN C020 ON C020_C004_Id = T007_C004_Id
                                WHERE T007_Numero_Lote = '{$numLote}' AND T007_C004_Id = '{$g['empresaAtual']}'
                                LIMIT 1");        
        if(mysql_num_rows($T007) == 0) {        
            return array(false,"Não foi localizado nenhuma nota vinculada a esse lote");        
        }

        $mConf = mysql_fetch_assoc($T007);        
        $mConf['pastaArquivoXML'] = "{$g['pathDadosAntigo']}nfe/xml";

        require_once("hardness/class/nfe4lote.php");
        $nfe = new NFe4Lote($mConf);
        
        return $nfe->enviarLoteNfe($numLote);      
    }

    public function consultarRecibo($T007_Id) {                        
        global $g;
        if(empty($T007_Id)) {
            return false;
        }
        
        $T007 = mysql_query("SELECT T007_Id,                                 
                                    T007_Empresa_Usuaria_Cnpj,
                                    T007_Empresa_Usuaria_Uf,
                                    T007_Empresa_Usuaria_Codigo_Estado_IBGE,
                                    T007_Ambiente_NFe,
                                    C004_Localizacao_Certificados,
                                    C020_NFe_Tipo_Certificado,                             
                                    C004_Senha_Certificados,
                                    C004_Id,                                    
                                    T007_Numero_Recibo_Nfe                          
                                FROM T007 
                                LEFT JOIN C004 ON C004_Id = T007_C004_Id
                                LEFT JOIN C020 ON C020_C004_Id = T007_C004_Id
                                WHERE T007_Id = '{$T007_Id}' AND T007_C004_Id = '{$g['empresaAtual']}'");       
        $mConf = mysql_fetch_assoc($T007);
        $mConf['pastaArquivoXML'] = "{$g['pathDadosAntigo']}nfe/xml";

        require_once("hardness/class/nfe4lote.php");
        $nfe = new NFe4Lote($mConf);
        
        return $nfe->consultarRecibo($mConf['T007_Numero_Recibo_Nfe']);        
    }  


